        {
            gameApi.TargetOwnServerObjectId = leader.ServerObjectId;
        }
    };
    var combatState = new StationaryCombatState
    {
        Fighting = true,
        CurrentTargetEntityId = 100,
        CurrentTargetServerObjectId = 5000
    };
