static Task TestTeamGroupDistancePersistsFromUiAsync()
{
    Exception? failure = null;
    var thread = new Thread(() =>
    {
        try
        {
            var settings = CreateScriptSettings();
            settings.Team = new TeamScriptSettings
            {
                Role = TeamRole.Leader,
                GroupDistanceMeters = 18.5D,
                Leader = new TeamLeaderScriptSettings
                {
                    Enabled = true,
                    TacticalMarkEnabled = true,
                    TacticalMarkKey = "F7"
                },
                Output = new TeamOutputScriptSettings
                {
                    OnlyAttackLeaderMarkedTarget = false,
                    TacticalMarkTargetingEnabled = true,
                    SelectTacticalMarkTargetKey = "F8"
                },
                Support = new TeamSupportScriptSettings
                {
                    TacticalMarkTargetingEnabled = true,
                    SelectTacticalMarkTargetKey = "F9"
                }
            };
            var configStore = new InMemoryAccountConfigStore(new AccountConfig
            {
                AccountName = "account1",
                ScriptSettings = settings
            });

            using var form = CreateAccountSettingsFormForTestsWithStore(configStore);
            SetComboSelectedIndexForTest(form, "settingsTabs", 6);
            form.Show();
            System.Windows.Forms.Application.DoEvents();
            AssertEqual("18.5", GetTextBoxTextForTest(form, "teamGroupDistanceTextBox"), "team group distance should load into UI");
            AssertFalse(
                !GetCheckBoxCheckedForTest(form, "teamLeaderTacticalMarkCheckBox"),
                "leader tactical mark switch should load into UI");
            AssertFalse(
                !GetCheckBoxCheckedForTest(form, "teamOutputTacticalMarkTargetingCheckBox"),
                "output tactical target switch should load into UI");
            AssertFalse(
                !GetCheckBoxCheckedForTest(form, "teamSupportTacticalMarkTargetingCheckBox"),
                "support tactical target switch should load into UI");
            AssertFalse(
                GetCheckBoxCheckedForTest(form, "teamOutputOnlyAttackLeaderMarkedTargetCheckBox"),
                "legacy output switch should remain independent from tactical targeting");

            AssertFalse(
                !GetControlVisibleForTest(form, "teamLeaderTacticalMarkKeyLabel"),
                "enabled leader tactical mark should show its key label");
            AssertFalse(
                !GetControlVisibleForTest(form, "teamLeaderTacticalMarkKeyButton"),
                "enabled leader tactical mark should show its key button");
            ClickControlForTest(form, "teamLeaderTacticalMarkCheckBox");
            AssertFalse(
                GetControlVisibleForTest(form, "teamLeaderTacticalMarkKeyLabel"),
                "disabled leader tactical mark should hide its key label");
            AssertFalse(
                GetControlVisibleForTest(form, "teamLeaderTacticalMarkKeyButton"),
                "disabled leader tactical mark should hide its key button");
            ClickControlForTest(form, "teamLeaderTacticalMarkCheckBox");

            SetComboSelectedIndexForTest(form, "teamRoleCombo", 1);
            AssertFalse(
                !GetControlVisibleForTest(form, "teamOutputSelectTacticalMarkTargetKeyLabel"),
                "enabled output tactical targeting should show its key label");
            AssertFalse(
                !GetControlVisibleForTest(form, "teamOutputSelectTacticalMarkTargetKeyButton"),
                "enabled output tactical targeting should show its key button");
            ClickControlForTest(form, "teamOutputTacticalMarkTargetingCheckBox");
            AssertFalse(
                GetControlVisibleForTest(form, "teamOutputSelectTacticalMarkTargetKeyLabel"),
                "disabled output tactical targeting should hide its key label");
            AssertFalse(
                GetControlVisibleForTest(form, "teamOutputSelectTacticalMarkTargetKeyButton"),
                "disabled output tactical targeting should hide its key button");
            ClickControlForTest(form, "teamOutputTacticalMarkTargetingCheckBox");

            SetComboSelectedIndexForTest(form, "teamRoleCombo", 2);
            AssertFalse(
                !GetControlVisibleForTest(form, "teamSupportSelectTacticalMarkTargetKeyLabel"),
                "enabled support tactical targeting should show its key label");
            AssertFalse(
                !GetControlVisibleForTest(form, "teamSupportSelectTacticalMarkTargetKeyButton"),
                "enabled support tactical targeting should show its key button");
            ClickControlForTest(form, "teamSupportTacticalMarkTargetingCheckBox");
            AssertFalse(
                GetControlVisibleForTest(form, "teamSupportSelectTacticalMarkTargetKeyLabel"),
                "disabled support tactical targeting should hide its key label");
            AssertFalse(
                GetControlVisibleForTest(form, "teamSupportSelectTacticalMarkTargetKeyButton"),
                "disabled support tactical targeting should hide its key button");
            ClickControlForTest(form, "teamSupportTacticalMarkTargetingCheckBox");
            SetComboSelectedIndexForTest(form, "teamRoleCombo", 0);

            SetTextBoxTextForTest(form, "teamGroupDistanceTextBox", "22.5");
            var saved = InvokeSaveCurrentSettingsForTest(form, out var error);
            AssertFalse(!saved, "team group distance save failed: " + error);

            var load = configStore.LoadAllAsync().GetAwaiter().GetResult();
            AssertFalse(!load.Success, "saved config should load");
            var savedDistance = load.Value!
                .Single(account => string.Equals(account.AccountName, "account1", StringComparison.OrdinalIgnoreCase))
                .ScriptSettings
                ?.Team
                ?.GroupDistanceMeters ?? 0.0D;
            AssertEqual(22.5D, savedDistance, "team group distance should persist from UI");
            var savedTeam = load.Value!
                .Single(account => string.Equals(account.AccountName, "account1", StringComparison.OrdinalIgnoreCase))
                .ScriptSettings
                ?.Team;
            AssertFalse(
                !(savedTeam?.Leader?.TacticalMarkEnabled ?? false),
                "leader tactical mark switch should persist from UI");
            AssertEqual("F7", savedTeam?.Leader?.TacticalMarkKey ?? string.Empty, "leader tactical mark key should persist from UI");
            AssertFalse(
                !(savedTeam?.Output?.TacticalMarkTargetingEnabled ?? false),
                "output tactical target switch should persist from UI");
            AssertEqual(
                "F8",
                savedTeam?.Output?.SelectTacticalMarkTargetKey ?? string.Empty,
                "output tactical target key should persist from UI");
            AssertFalse(
                !(savedTeam?.Support?.TacticalMarkTargetingEnabled ?? false),
                "support tactical target switch should persist from UI");
            AssertEqual(
                "F9",
                savedTeam?.Support?.SelectTacticalMarkTargetKey ?? string.Empty,
                "support tactical target key should persist from UI");
            AssertFalse(
                savedTeam?.Output?.OnlyAttackLeaderMarkedTarget ?? true,
                "legacy output switch should preserve its own value");
        }
        catch (Exception ex)
        {
            failure = ex;
        }
    });

    thread.SetApartmentState(ApartmentState.STA);
    thread.Start();
    thread.Join();

    if (failure is not null)
    {
        System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(failure).Throw();
    }

    return Task.CompletedTask;
}

