            InventoryItems = new[]
            {
                new InventoryItemSnapshot(167000450, 10, "green-manastone-a", 1, 0, false, 24, 2),
                new InventoryItemSnapshot(167000451, 11, "green-manastone-b", 1, 1, false, 24, 2),
                new InventoryItemSnapshot(1001, 12, "kept", 1, 2, false, 1, 4),
                new InventoryItemSnapshot(1002, 13, "filler-3", 1, 3, false, 1, 1),
                new InventoryItemSnapshot(1003, 14, "filler-4", 1, 4, false, 1, 1),
                new InventoryItemSnapshot(1004, 15, "filler-5", 1, 5, false, 1, 1),
                new InventoryItemSnapshot(1005, 16, "filler-6", 1, 6, false, 1, 1)
            }
        };
        keyboard.AfterPress = key =>
        {
            if (key == "NumPad7")
            {
                gameApi.Player = gameApi.Player with
                {
                    Position = new Vector3Snapshot(100, 0, 0),
                    CapturedAt = DateTimeOffset.Now
                };
            }
            else if (key == "F8")
            {
                gameApi.TargetEntityId = 77;
                gameApi.TargetServerObjectId = 7700;
                gameApi.TargetName = cleanupNpcName;
                gameApi.TargetCurrentHp = 0;
                gameApi.TargetMaxHp = 0;
            }
            else if (key == "I")
            {
                gameApi.InventoryWindow = CreateInventoryWindow(!gameApi.InventoryWindow.IsOpen, 0.0, 0.0);
            }
        };

        var rules = BagCleanupRuleCatalog.CreateDefaultRules();
        rules.First(rule => rule.Key == BagCleanupRuleCatalog.GreenManastone).Enabled = true;
        var settings = CreateScriptSettings();
        settings.Paths.TownReturnKey = "NumPad7";
        settings.Paths.MaintenancePathName = "cleanup-path";
        settings.Maintenance = new MaintenanceScriptSettings
        {
            BagCleanupEnabled = true,
            BagCleanupThreshold = 5,
            BagCleanupRules = rules,
            BagCleanupSellItemClickX = 100,
            BagCleanupSellItemClickY = 200,
            BagCleanupSellButtonClickX = 300,
            BagCleanupSellButtonClickY = 400
        };
        var pathStore = new InMemorySharedPathStore(new SharedPathDocument
        {
            Name = "cleanup-path",
            CleanupNpcName = cleanupNpcName,
            Points = new List<SharedPathPoint>
            {
                new() { X = 1, Y = 0, Z = 0 },
                new() { X = 2, Y = 0, Z = 0 }
            }
        });
        var pathCalls = new List<string>();
        var controller = new BagCleanupController(
            keyboard,
            pathStore,
            (_, pathName, points) =>
            {
                pathCalls.Add(pathName + ":" + points.Count);
                return Task.FromResult(OperationResult.Ok());
            });
        var state = new BagCleanupState();
        var context = CreateContext(settings, gameApi, logger);
        BagCleanupTickResult? last = null;
        for (var i = 0; i < 30; i++)
        {
            last = await controller.TickAfterLootAsync(context, state).ConfigureAwait(false);
            if (last.Status == BagCleanupTickStatus.RecoverableFailure ||
                last.Status == BagCleanupTickStatus.FatalFailure ||
                last.Status == BagCleanupTickStatus.Completed)
            {
                break;
            }
        }

        AssertEqual(BagCleanupTickStatus.RecoverableFailure, last?.Status ?? BagCleanupTickStatus.FatalFailure, "cleanup failure should be recoverable");
        AssertEqual("money_verify_failed", last?.Reason ?? string.Empty, "money verify failure should be logged as clear reason");
        AssertFalse(!keyboard.Keys.Contains("Space"), "failed cleanup should still run the completion jump before returning");
        AssertSequence(new[] { "cleanup-path:2", "cleanup-path 返回:2" }, pathCalls.ToArray(), "money verify failure should reverse the cleanup path");
        AssertFalse(state.LastFailedAt == DateTimeOffset.MinValue, "failure should start failure cooldown");
        AssertFalse(!logger.Entries.Any(entry => entry.EventName == "bag_cleanup.failed"), "cleanup failure should be logged");
        AssertFalse(!logger.Entries.Any(entry => entry.EventName == "bag_cleanup.failure.returning"), "cleanup failure should log reverse-path recovery");
        AssertFalse(
            !logger.Entries.Any(entry =>
                entry.EventName == "bag_cleanup.completion_jump.complete" &&
                entry.Fields.TryGetValue("cleanupSucceeded", out var succeeded) &&
                succeeded is false),
            "failed cleanup should log completion jump before recovery");
        AssertFalse(
            !logger.Entries.Any(entry =>
                entry.EventName == "bag_cleanup.failed" &&
                entry.Fields.TryGetValue("returnedByReversePath", out var returned) &&
                returned is bool boolValue &&
                boolValue),
            "cleanup failure should log that reverse path completed");

        var keyCountAfterFailure = keyboard.Keys.Count;
        var skipped = await controller.TickAfterLootAsync(context, state).ConfigureAwait(false);
        AssertEqual(BagCleanupTickStatus.Skipped, skipped.Status, "cleanup should skip during failure cooldown");
        AssertEqual("cleanup_failure_cooldown", skipped.Reason, "failure cooldown reason");
        AssertEqual(keyCountAfterFailure, keyboard.Keys.Count, "failure cooldown should not press more keys");
        AssertFalse(!logger.Entries.Any(entry => entry.EventName == "bag_cleanup.skip.failure_cooldown"), "failure cooldown skip should be logged");
    }
    finally
    {
        Environment.SetEnvironmentVariable("ROADHOG_BAG_CLEANUP_TOWN_RETURN_SETTLE_MS", previousTownSettle);
        Environment.SetEnvironmentVariable("ROADHOG_BAG_CLEANUP_SELL_VERIFY_DELAY_MS", previousVerify);
        Environment.SetEnvironmentVariable("ROADHOG_BAG_CLEANUP_POINT_HOVER_MS", previousPointHover);
        Environment.SetEnvironmentVariable("ROADHOG_BAG_SELL_REGISTER_HOVER_MS", previousRegisterHover);
        Environment.SetEnvironmentVariable("ROADHOG_BAG_CLEANUP_SELL_ITEM_ENTRY_DELAY_MIN_MS", previousSellItemEntryDelayMin);
        Environment.SetEnvironmentVariable("ROADHOG_BAG_CLEANUP_SELL_ITEM_ENTRY_DELAY_MAX_MS", previousSellItemEntryDelayMax);
        Environment.SetEnvironmentVariable("ROADHOG_DEATH_REVIVE_MOUSE_RESET_COUNT", previousMouseReset);
        Environment.SetEnvironmentVariable("ROADHOG_DEATH_REVIVE_MOUSE_STEP_DELAY_MS", previousMouseStep);
        Environment.SetEnvironmentVariable("ROADHOG_BAG_CLEANUP_NPC_SELECT_ATTEMPTS", previousNpcAttempts);
        Environment.SetEnvironmentVariable("ROADHOG_BAG_CLEANUP_NPC_SELECT_DELAY_MS", previousNpcSelectDelay);
        Environment.SetEnvironmentVariable("ROADHOG_BAG_CLEANUP_TOWN_RETURN_MIN_DISTANCE", previousTownMinDistance);
        Environment.SetEnvironmentVariable("ROADHOG_BAG_CLEANUP_FAILURE_COOLDOWN_MS", previousFailureCooldown);
    }
}

static async Task TestBagCleanupNameListStoreRoundTripAndLegacyAsync()
{
    var directory = Path.Combine(Path.GetTempPath(), "roadhog-bag-name-lists-" + Guid.NewGuid().ToString("N"));
    var jsonPath = Path.Combine(directory, JsonBagCleanupNameListStore.DefaultFileName);
    var legacyPath = Path.Combine(directory, JsonBagCleanupNameListStore.LegacyFileName);
    Directory.CreateDirectory(directory);
    try
    {
        var store = new JsonBagCleanupNameListStore(jsonPath, legacyPath);
        var save = await store.SaveAsync(new BagCleanupNameListsDocument
        {
            Whitelist = new List<string> { " 保留 ", "保留", "闪光" },
            Blacklist = new List<string> { " 丢弃 ", "丢弃" }
        }).ConfigureAwait(false);
        AssertFalse(!save.Success, "name-list json should save");

        var text = await File.ReadAllTextAsync(jsonPath).ConfigureAwait(false);
        AssertFalse(!text.Contains("\"version\": 1", StringComparison.Ordinal), "name-list json should persist version");
        AssertFalse(!text.Contains("\"whitelist\"", StringComparison.Ordinal), "name-list json should persist whitelist");
        AssertFalse(!text.Contains("\"blacklist\"", StringComparison.Ordinal), "name-list json should persist blacklist");

        var load = await store.LoadAsync().ConfigureAwait(false);
        AssertFalse(!load.Success || load.Value is not { Found: true, Document: { } }, "name-list json should load");
        AssertEqual(BagCleanupNameListsSource.Json, load.Value!.Source, "json should be the primary source");
        AssertSequence(new[] { "保留", "闪光" }, load.Value.Document!.Whitelist.ToArray(), "whitelist should trim and deduplicate");
        AssertSequence(new[] { "丢弃" }, load.Value.Document.Blacklist.ToArray(), "blacklist should trim and deduplicate");

        var copiedDirectory = Path.Combine(directory, "copied-client", "config");
        Directory.CreateDirectory(copiedDirectory);
        var copiedPath = Path.Combine(copiedDirectory, JsonBagCleanupNameListStore.DefaultFileName);
        File.Copy(jsonPath, copiedPath);
        var copiedLoad = await new JsonBagCleanupNameListStore(copiedPath).LoadAsync().ConfigureAwait(false);
        AssertFalse(!copiedLoad.Success || copiedLoad.Value is not { Found: true, Document: { } }, "copied client should load the same single file");
        AssertSequence(new[] { "保留", "闪光" }, copiedLoad.Value!.Document!.Whitelist.ToArray(), "copied whitelist should remain reusable");
        AssertSequence(new[] { "丢弃" }, copiedLoad.Value.Document.Blacklist.ToArray(), "copied blacklist should remain reusable");

        File.Delete(jsonPath);
        await File.WriteAllLinesAsync(legacyPath, new[] { " 旧保留 ", "旧保留", "旧闪光" }).ConfigureAwait(false);
        var legacyLoad = await store.LoadAsync().ConfigureAwait(false);
        AssertFalse(!legacyLoad.Success || legacyLoad.Value is not { Found: true, Document: { } }, "legacy whitelist should load");
        AssertEqual(BagCleanupNameListsSource.LegacyText, legacyLoad.Value!.Source, "legacy text should be reported as source");
        AssertSequence(new[] { "旧保留", "旧闪光" }, legacyLoad.Value.Document!.Whitelist.ToArray(), "legacy lines should become whitelist");
        AssertEqual(0, legacyLoad.Value.Document.Blacklist.Count, "legacy file should default blacklist empty");

        await File.WriteAllTextAsync(jsonPath, "{\"version\":1,\"whitelist\":[]}").ConfigureAwait(false);
        var invalidLoad = await store.LoadAsync().ConfigureAwait(false);
        AssertFalse(invalidLoad.Success, "present invalid json must fail closed instead of falling back");
    }
    finally
    {
        DeleteDirectoryIfExists(directory);
    }
}

static Task TestBagCleanupMatcherSeparatesDiscardAndResolvesConflictsAsync()
{
    var rules = BagCleanupRuleCatalog.CreateDefaultRules();
    var green = rules.First(rule => rule.Key == BagCleanupRuleCatalog.GreenEquipment);
    green.Enabled = true;
    green.Action = BagCleanupAction.Discard;
    var white = rules.First(rule => rule.Key == BagCleanupRuleCatalog.WhiteEquipment);
    white.Enabled = true;
    white.Action = BagCleanupAction.Discard;
    rules.Add(new BagCleanupRuleConfig
    {
        Key = "equipment.green.sell_conflict",
        DisplayName = "green sell conflict",
        Category = "equipment",
        Quality = "green",
        Enabled = true,
        Action = BagCleanupAction.Sell
    });
    var settings = new MaintenanceScriptSettings { BagCleanupRules = rules };
    var greenItem = new InventoryItemSnapshot(1001, 11, "green equipment", 1, 0, false, 1, 2);
    var whiteItem = new InventoryItemSnapshot(1002, 12, "white equipment", 1, 1, false, 1, 1);

    var sell = BagCleanupItemMatcher.SelectSellRegistrationItems(new[] { greenItem, whiteItem }, settings);
    var discard = BagCleanupItemMatcher.SelectDiscardItems(new[] { greenItem, whiteItem }, settings);
    var conflicts = BagCleanupItemMatcher.SelectSellDiscardConflicts(new[] { greenItem, whiteItem }, settings);

    AssertSequence(new[] { 11UL }, sell.Select(item => item.InstanceId).ToArray(), "sell rule should retain the conflicted item");
    AssertSequence(new[] { 12UL }, discard.Select(item => item.InstanceId).ToArray(), "discard should exclude sell conflicts");
    AssertSequence(new[] { 11UL }, conflicts.Select(item => item.InstanceId).ToArray(), "matcher should report sell discard conflicts");
    return Task.CompletedTask;
}

static Task TestBagCleanupMatcherAppliesWhitelistThenBlacklistPrecedenceAsync()
{
    var rules = BagCleanupRuleCatalog.CreateDefaultRules();
    var green = rules.First(rule => rule.Key == BagCleanupRuleCatalog.GreenEquipment);
    green.Enabled = true;
    green.Action = BagCleanupAction.Sell;
    var white = rules.First(rule => rule.Key == BagCleanupRuleCatalog.WhiteEquipment);
    white.Enabled = true;
    white.Action = BagCleanupAction.Discard;
    var settings = new MaintenanceScriptSettings
    {
        BagCleanupRules = rules,
        BagCleanupExcludedItemNames = new List<string> { "protect" },
        BagCleanupDiscardItemNameKeywords = new List<string> { "tRaSh" }
    };
    var items = new[]
    {
        new InventoryItemSnapshot(1001, 11, "protect trash green", 1, 0, false, 1, 2),
        new InventoryItemSnapshot(1002, 12, "TRASH green", 1, 1, false, 1, 2),
        new InventoryItemSnapshot(1003, 13, "normal green", 1, 2, false, 1, 2),
        new InventoryItemSnapshot(1004, 14, "normal white", 1, 3, false, 1, 1),
        new InventoryItemSnapshot(1005, 15, "trash equipped", 1, 4, true, 1, 2)
    };

    var sell = BagCleanupItemMatcher.SelectSellRegistrationItems(items, settings);
    var discard = BagCleanupItemMatcher.SelectDiscardItems(items, settings);
    var conflicts = BagCleanupItemMatcher.SelectSellDiscardConflicts(items, settings);

    AssertSequence(new[] { 13UL }, sell.Select(item => item.InstanceId).ToArray(), "blacklist should remove sell matches while whitelist protects all actions");
    AssertSequence(new[] { 12UL, 14UL }, discard.Select(item => item.InstanceId).ToArray(), "blacklist should force discard before normal discard rules");
    AssertEqual(0, conflicts.Count, "blacklist resolution should not be reported as a normal sell-wins conflict");
    AssertEqual(1, BagCleanupItemMatcher.CountWhitelistedBagItems(items, settings), "whitelist match count");
    AssertEqual(1, BagCleanupItemMatcher.CountBlacklistedBagItems(items, settings), "blacklist count should exclude whitelist and equipped items");
    return Task.CompletedTask;
}

static async Task TestBagCleanupBlacklistStartsDiscardDuringFullCleanupCooldownAsync()
{
    var logger = new InMemoryRoadhogLogger();
    var keyboard = new RecordingKeyboardInput();
    var settings = CreateScriptSettings();
    settings.Paths.DeathReviveClickX = 680;
    settings.Paths.DeathReviveClickY = 467;
    settings.Maintenance = new MaintenanceScriptSettings
    {
        BagCleanupEnabled = true,
        BagCleanupThreshold = 2,
        BagCleanupRules = BagCleanupRuleCatalog.CreateDefaultRules(),
        BagCleanupDiscardItemNameKeywords = new List<string> { "trash" },
        BagCleanupDiscardConfirmClickX = 650,
        BagCleanupDiscardConfirmClickY = 470
    };
    var gameApi = CreateSafeDiscardGameApi(
        capacity: 2,
        new InventoryItemSnapshot(1001, 41, "trash item", 1, 0, false, 99, 4));
    gameApi.InventoryWindow = CreateInventoryWindow(true, 0.0, 0.0);
    var state = new BagCleanupState();
    state.MarkCompleted(DateTimeOffset.Now);
    WireDiscardInputSimulation(keyboard, gameApi, state, firstItemUsesSpecialConfirm: false);
    var controller = new BagCleanupController(
        keyboard,
        new InMemorySharedPathStore(),
        (_, _, _) => Task.FromResult(OperationResult.Ok()));

    var result = await controller
        .TickAfterLootAsync(CreateContext(settings, gameApi, logger), state)
        .ConfigureAwait(false);

    AssertEqual(BagCleanupTickStatus.Running, result.Status, "blacklist discard should bypass full-cleanup cooldown");
    AssertEqual("discard_started", result.Reason, "blacklist should start the existing discard flow");
    AssertFalse(!state.DiscardActive, "blacklist-only settings should enter discard state");
    var check = logger.Entries.Last(entry => entry.EventName == "bag_cleanup.check");
    AssertEqual(1, Convert.ToInt32(check.Fields["blacklistMatchCount"]), "blacklist match should be logged");

    for (var i = 0; i < 40 && result.Status == BagCleanupTickStatus.Running; i++)
    {
        result = await controller
            .TickAfterLootAsync(CreateContext(settings, gameApi, logger), state)
            .ConfigureAwait(false);
    }

    AssertEqual("discard_completed_capacity_recovered", result.Reason, "blacklist should finish through the existing discard flow");
    AssertFalse(gameApi.InventoryItems.Any(item => item.InstanceId == 41), "blacklisted item should be verified removed");
}

static async Task TestBagCleanupDiscardDeletesAllCandidatesAndClosesInventoryAsync()
{
    var logger = new InMemoryRoadhogLogger();
    var keyboard = new RecordingKeyboardInput();
    var settings = CreateDiscardScriptSettings(BagCleanupRuleCatalog.GreenManastone, threshold: 2);
    var gameApi = CreateSafeDiscardGameApi(
        capacity: 5,
        new InventoryItemSnapshot(167000450, 10, "green-manastone-a", 1, 0, false, 24, 2),
        new InventoryItemSnapshot(167000451, 11, "green-manastone-b", 1, 1, false, 24, 2),
        new InventoryItemSnapshot(1001, 12, "kept-a", 1, 2, false, 1, 4),
        new InventoryItemSnapshot(1002, 13, "kept-b", 1, 3, false, 1, 4));
    gameApi.InventoryWindow = CreateInventoryWindow(true, 0.0, 0.0);
    var state = new BagCleanupState();
    var confirmClicks = WireDiscardInputSimulation(keyboard, gameApi, state, firstItemUsesSpecialConfirm: true);
    var controller = new BagCleanupController(
        keyboard,
        new InMemorySharedPathStore(),
        (_, _, _) => Task.FromResult(OperationResult.Ok()));
    var context = CreateContext(settings, gameApi, logger);

    BagCleanupTickResult? last = null;
    for (var i = 0; i < 80; i++)
    {
        last = await controller.TickAfterLootAsync(context, state).ConfigureAwait(false);
        if (last.Status != BagCleanupTickStatus.Running)
        {
            break;
        }
    }

    AssertEqual(BagCleanupTickStatus.Skipped, last?.Status ?? BagCleanupTickStatus.FatalFailure, "discard-only cleanup should finish locally");
    AssertEqual("discard_completed_capacity_recovered", last?.Reason ?? string.Empty, "discard should resume combat after recovering capacity");
    AssertFalse(gameApi.InventoryItems.Any(item => item.InstanceId is 10UL or 11UL), "all discard candidates should be removed");
    AssertFalse(gameApi.InventoryWindow.IsOpen, "inventory must close after all discard candidates");
    AssertEqual(3, confirmClicks(), "special plus normal items should require three confirmation clicks");
    AssertFalse(!keyboard.MouseCommands.Contains("move:650,470"), "configured discard confirmation coordinate should be used");
    AssertFalse(keyboard.Keys.Contains(settings.Paths.TownReturnKey), "capacity recovery should not start full cleanup");
    AssertFalse(state.Active, "discard-only completion should reset cleanup state");
    AssertFalse(!logger.Entries.Any(entry => entry.EventName == "bag_cleanup.discard.complete"), "discard completion should be logged");
}

static async Task TestBagCleanupDiscardTransitionsToFullCleanupAfterExhaustionAsync()
{
    var logger = new InMemoryRoadhogLogger();
    var keyboard = new RecordingKeyboardInput();
    var settings = CreateDiscardScriptSettings(BagCleanupRuleCatalog.WhiteEquipment, threshold: 2);
    var sellRule = settings.Maintenance.BagCleanupRules.First(rule => rule.Key == BagCleanupRuleCatalog.GreenManastone);
    sellRule.Enabled = true;
    sellRule.Action = BagCleanupAction.Sell;
    settings.Paths.TownReturnKey = "NumPad7";
    settings.Paths.MaintenancePathName = "cleanup-path";
    var gameApi = CreateSafeDiscardGameApi(
        capacity: 5,
        new InventoryItemSnapshot(1001001, 20, "white-equipment", 1, 0, false, 1, 1),
        new InventoryItemSnapshot(167000450, 21, "green-manastone", 1, 1, false, 24, 2),
        new InventoryItemSnapshot(1002, 22, "kept-a", 1, 2, false, 8, 4),
        new InventoryItemSnapshot(1003, 23, "kept-b", 1, 3, false, 8, 4),
        new InventoryItemSnapshot(1004, 24, "kept-c", 1, 4, false, 8, 4));
    gameApi.InventoryWindow = CreateInventoryWindow(true, 0.0, 0.0);
    var state = new BagCleanupState();
    WireDiscardInputSimulation(keyboard, gameApi, state, firstItemUsesSpecialConfirm: false);
    var controller = new BagCleanupController(
        keyboard,
        new InMemorySharedPathStore(),
        (_, _, _) => Task.FromResult(OperationResult.Ok()));
    var context = CreateContext(settings, gameApi, logger);

    BagCleanupTickResult? last = null;
    for (var i = 0; i < 40; i++)
    {
        last = await controller.TickAfterLootAsync(context, state).ConfigureAwait(false);
        if (state.Step == BagCleanupStep.WaitSafeToReturn)
        {
            break;
        }
    }

    AssertEqual(BagCleanupTickStatus.Running, last?.Status ?? BagCleanupTickStatus.FatalFailure, "full cleanup transition should keep running");
    AssertEqual(BagCleanupStep.WaitSafeToReturn, state.Step, "full cleanup should start only after discard candidates are exhausted");
    AssertFalse(gameApi.InventoryItems.Any(item => item.InstanceId == 20), "discard candidate should be removed before full cleanup");
    AssertFalse(gameApi.InventoryWindow.IsOpen, "inventory should close before full cleanup return starts");
    AssertFalse(!gameApi.InventoryItems.Any(item => item.InstanceId == 21), "sell candidate must remain for NPC cleanup");
}

static async Task TestBagCleanupDiscardAbortsBeforeConfirmAsync()
{
    var logger = new InMemoryRoadhogLogger();
    var keyboard = new RecordingKeyboardInput();
    var settings = CreateDiscardScriptSettings(BagCleanupRuleCatalog.GreenManastone, threshold: 2);
    var target = new InventoryItemSnapshot(167000450, 30, "green-manastone", 1, 0, false, 24, 2);
    var gameApi = CreateSafeDiscardGameApi(capacity: 3, target, new InventoryItemSnapshot(1001, 31, "kept", 1, 1, false, 1, 4));
    gameApi.InventoryWindow = CreateInventoryWindow(true, 0.0, 0.0);
    gameApi.WorldObjects = new[]
    {
        new WorldObjectSnapshot(200, 2000, "attacker", "monster", new Vector3Snapshot(3, 0, 0), 3, 100, 100, 1, true)
    };
    keyboard.AfterPress = key =>
    {
        if (key == "I")
        {
            gameApi.InventoryWindow = CreateInventoryWindow(false, 0.0, 0.0);
        }
    };
    var state = new BagCleanupState();
    state.StartDiscard(1, 2, 1);
    state.SetDiscardWindow(gameApi.InventoryWindow);
    state.SetDiscardTarget(target);
    state.Advance(BagCleanupStep.WaitDiscardConfirm);
    var controller = new BagCleanupController(
        keyboard,
        new InMemorySharedPathStore(),
        (_, _, _) => Task.FromResult(OperationResult.Ok()));

    var result = await controller.TickAfterLootAsync(CreateContext(settings, gameApi, logger), state).ConfigureAwait(false);

    AssertEqual(BagCleanupTickStatus.Skipped, result.Status, "attack before confirm should abandon discard");
    AssertEqual("discard_interrupted_by_attack", result.Reason, "attack interruption reason");
    AssertFalse(gameApi.InventoryWindow.IsOpen, "attack interruption should close inventory");
    AssertFalse(!gameApi.InventoryItems.Any(item => item.InstanceId == target.InstanceId), "target must remain when confirm was not visible");
    AssertFalse(keyboard.MouseCommands.Contains("move:650,470"), "confirm coordinate must not be clicked before confirm appears");
    AssertFalse(state.Active, "interrupted discard state should reset");
    AssertEqual(DateTimeOffset.MinValue, state.LastFailedAt, "attack interruption must not start failure cooldown");
}

static async Task TestBagCleanupDiscardConfirmsBeforeAttackHandoffAsync()
{
    var logger = new InMemoryRoadhogLogger();
    var keyboard = new RecordingKeyboardInput();
    var settings = CreateDiscardScriptSettings(BagCleanupRuleCatalog.GreenManastone, threshold: 2);
    var target = new InventoryItemSnapshot(167000450, 40, "green-manastone", 1, 0, false, 24, 2);
    var gameApi = CreateSafeDiscardGameApi(capacity: 3, target, new InventoryItemSnapshot(1001, 41, "kept", 1, 1, false, 1, 4));
    gameApi.InventoryWindow = CreateInventoryWindow(true, 0.0, 0.0);
    gameApi.InventoryDiscardConfirm = new InventoryDiscardConfirmSnapshot(
        true,
        40,
        InventoryDiscardConfirmKind.Normal,
        336,
        0x1234,
        DateTimeOffset.Now);
    var confirmMouseDown = false;
    keyboard.AfterMouseDown = button =>
    {
        if (button == RoadhogMouseButton.Left && gameApi.InventoryDiscardConfirm.IsOpen)
        {
            confirmMouseDown = true;
        }
    };
    keyboard.AfterMouseUp = button =>
    {
        if (button != RoadhogMouseButton.Left || !confirmMouseDown)
        {
            return;
        }

        confirmMouseDown = false;
        gameApi.InventoryItems = gameApi.InventoryItems.Where(item => item.InstanceId != target.InstanceId).ToArray();
        gameApi.InventoryDiscardConfirm = InventoryDiscardConfirmSnapshot.Closed(DateTimeOffset.Now);
    };
    keyboard.AfterPress = key =>
    {
        if (key == "I")
        {
            gameApi.InventoryWindow = CreateInventoryWindow(false, 0.0, 0.0);
        }
    };
    var state = new BagCleanupState();
    state.StartDiscard(1, 2, 1);
    state.SetDiscardWindow(gameApi.InventoryWindow);
    state.SetDiscardTarget(target);
    state.MarkDiscardConfirmSeen();
    state.Advance(BagCleanupStep.ClickDiscardConfirm);
    var controller = new BagCleanupController(
        keyboard,
        new InMemorySharedPathStore(),
        (_, _, _) => Task.FromResult(OperationResult.Ok()));

    var result = await controller
        .AbortDiscardForAttackAsync(CreateContext(settings, gameApi, logger), state, "attacker")
        .ConfigureAwait(false);

    AssertEqual(BagCleanupTickStatus.Skipped, result.Status, "confirm-visible attack should still hand off to combat");
    AssertFalse(gameApi.InventoryItems.Any(item => item.InstanceId == target.InstanceId), "visible confirm must be clicked before combat handoff");
    AssertFalse(!keyboard.MouseCommands.Contains("move:650,470"), "confirm-visible interruption should use customer coordinate");
    AssertFalse(gameApi.InventoryWindow.IsOpen, "inventory should close after confirming interrupted discard");
    AssertFalse(state.Active, "interrupted confirm completion should not resume discard");
    AssertEqual(DateTimeOffset.MinValue, state.LastFailedAt, "confirm-visible interruption must not start failure cooldown");
}

static async Task TestBagCleanupDiscardUsesLatchedConfirmAfterRereadFailureAsync()
{
    var logger = new InMemoryRoadhogLogger();
    var keyboard = new RecordingKeyboardInput();
    var settings = CreateDiscardScriptSettings(BagCleanupRuleCatalog.GreenManastone, threshold: 2);
    var target = new InventoryItemSnapshot(167000450, 42, "green-manastone", 1, 0, false, 24, 2);
    var gameApi = CreateSafeDiscardGameApi(capacity: 3, target);
    gameApi.InventoryWindow = CreateInventoryWindow(true, 0.0, 0.0);
    var confirm = new InventoryDiscardConfirmSnapshot(
        true,
        42,
        InventoryDiscardConfirmKind.Normal,
        336,
        0x1234,
        DateTimeOffset.Now);
    gameApi.InventoryDiscardConfirm = confirm;
    gameApi.InventoryDiscardConfirmReadResults.Enqueue(
        OperationResult<InventoryDiscardConfirmSnapshot>.Fail("transient confirm reread failure"));
    var confirmMouseDown = false;
    keyboard.AfterMouseDown = button =>
    {
        if (button == RoadhogMouseButton.Left && gameApi.InventoryDiscardConfirm.IsOpen)
        {
            confirmMouseDown = true;
        }
    };
    keyboard.AfterMouseUp = button =>
    {
        if (button != RoadhogMouseButton.Left || !confirmMouseDown)
        {
            return;
        }

        confirmMouseDown = false;
        gameApi.InventoryItems = gameApi.InventoryItems
            .Where(item => item.InstanceId != target.InstanceId)
            .ToArray();
        gameApi.InventoryDiscardConfirm = InventoryDiscardConfirmSnapshot.Closed(DateTimeOffset.Now);
    };
    var state = new BagCleanupState();
    state.StartDiscard(1, 2, 1);
    state.SetDiscardWindow(gameApi.InventoryWindow);
    state.SetDiscardTarget(target);
    state.MarkDiscardConfirmSeen(confirm);
    state.Advance(BagCleanupStep.ClickDiscardConfirm);
    var controller = new BagCleanupController(
        keyboard,
        new InMemorySharedPathStore(),
        (_, _, _) => Task.FromResult(OperationResult.Ok()));

    var result = await controller.TickAfterLootAsync(CreateContext(settings, gameApi, logger), state).ConfigureAwait(false);

    AssertEqual(BagCleanupTickStatus.Running, result.Status, "hidden confirm fault should keep discard running");
    AssertEqual("discard_confirm_clicked", result.Reason, "next normal confirm snapshot should use the normal completion path");
    AssertFalse(gameApi.InventoryItems.Any(item => item.InstanceId == target.InstanceId), "normal confirm snapshot should discard the same item");
    AssertFalse(!keyboard.MouseCommands.Contains("move:650,470"), "normal confirm snapshot should use the configured customer coordinate");
    AssertEqual(1, state.DiscardConfirmClickCount, "normal confirm should count as exactly one click");
    AssertFalse(
        !logger.Entries.Any(entry => entry.EventName == "snapshot.read.retry"),
        "transient confirm fault should be contained and logged below bag cleanup");
    AssertFalse(
        logger.Entries.Any(entry => entry.EventName == "bag_cleanup.discard.confirm_latch_fallback"),
        "bag cleanup must not use a business-layer read fallback");
}

