    var result = await controller.TickAfterLootAsync(context, state).ConfigureAwait(false);

    AssertEqual(BagCleanupTickStatus.Running, result.Status, "account3 inventory cycle should be hidden below cleanup");
    AssertEqual("discard_verified", result.Reason, "next higher inventory snapshot should verify deletion");
    AssertEqual(BagCleanupStep.ReadDiscardCandidates, state.Step, "cleanup should continue with the remaining queue");
    AssertEqual(1, state.DiscardedItemCount, "verified deletion should remain counted");
    AssertFalse(gameApi.InventoryReadCount < 3, "inventory snapshot reader should retry after the injected cycle");
    AssertFalse(
        logger.Entries.Any(entry => entry.EventName == "bag_cleanup.discard.failed"),
        "business cleanup must never receive the inventory tree fault");
}

static Task TestBagCleanupBusinessReadBoundaryAsync()
{
    var directory = new DirectoryInfo(AppContext.BaseDirectory);
    while (directory is not null &&
           !Directory.Exists(Path.Combine(directory.FullName, "Roadhog", "Application", "BagCleanup")))
    {
        directory = directory.Parent;
    }

    AssertFalse(directory is null, "repository root should be discoverable for architecture check");
    var bagDirectory = Path.Combine(directory!.FullName, "Roadhog", "Application", "BagCleanup");
    AssertFalse(
        File.Exists(Path.Combine(bagDirectory, "BagCleanupGameApi.cs")),
        "the direct bag-cleanup read entry must remain deleted");

    var forbidden = new[]
    {
        "GameApiReadContext",
        "IRoadhogGameApi",
        "IRoadhogScopedGameApi",
        "BypassMemoryCache",
        "RequireFresh",
        ".GameApi"
    };
    foreach (var file in Directory.GetFiles(bagDirectory, "*.cs", SearchOption.TopDirectoryOnly))
    {
        var source = File.ReadAllText(file);
        foreach (var token in forbidden)
        {
            AssertFalse(
                source.Contains(token, StringComparison.OrdinalIgnoreCase),
                Path.GetFileName(file) + " must not reference raw read token " + token);
        }
    }

    var controllerSource = File.ReadAllText(Path.Combine(bagDirectory, "BagCleanupController.cs"));
    AssertFalse(
        controllerSource.Contains("OperationResult<", StringComparison.Ordinal),
        "BagCleanupController must not receive typed data-read OperationResult values");

    var applicationDirectory = Path.Combine(directory.FullName, "Roadhog", "Application");
    foreach (var file in Directory.GetFiles(applicationDirectory, "*.cs", SearchOption.AllDirectories))
    {
        var source = File.ReadAllText(file);
        foreach (var token in forbidden)
        {
            AssertFalse(
                source.Contains(token, StringComparison.OrdinalIgnoreCase),
                Path.GetRelativePath(applicationDirectory, file) + " must not reference raw read token " + token);
        }
    }

    var dataQualityTokens = new[]
    {
        ".DataAvailable",
        "HasReliableHealth",
        "HealthFields",
        "ConsecutiveMissingRead",
        "ConsecutiveMissingSnapshot",
        "snapshot_unavailable",
        "player_read_failed",
        "channel_snapshot_unavailable",
        "LastValidChannel",
        "RequireFresh",
        "TryReadFresh",
        "ReadCurrent",
        "forceRefresh"
    };
    foreach (var file in Directory.GetFiles(applicationDirectory, "*.cs", SearchOption.AllDirectories))
    {
        var source = File.ReadAllText(file);
        foreach (var token in dataQualityTokens)
        {
            AssertFalse(
                source.Contains(token, StringComparison.OrdinalIgnoreCase),
                Path.GetRelativePath(applicationDirectory, file) +
                " must trust official publications instead of inspecting data quality token " + token);
        }
    }

    var workerContextSource = File.ReadAllText(
        Path.Combine(applicationDirectory, "Workers", "AccountWorkerContext.cs"));
    AssertFalse(
        workerContextSource.Contains("public IRoadhogGameApi", StringComparison.Ordinal),
        "AccountWorkerContext must not expose the raw game API to business consumers");

    var exportedTypes = typeof(RoadhogRuntime).Assembly.GetExportedTypes();
    foreach (var rawTypeName in new[]
             {
                 "IRoadhogGameApi",
                 "IRoadhogScopedGameApi",
                 "GameApiReadContext",
                 "AionVmmGameApi",
                 "MockRoadhogGameApi",
                 "ToolProcessApiClient",
                 "WorldObjectReadResult",
                 "SummonedPetRosterReadResult"
             })
    {
        AssertFalse(
            exportedTypes.Any(type => string.Equals(type.Name, rawTypeName, StringComparison.Ordinal)),
            "raw provider type must not be publicly exported: " + rawTypeName);
    }

    foreach (var method in typeof(IRoadhogSnapshotReader).GetMethods())
    {
        AssertFalse(
            method.Name.Contains("Fresh", StringComparison.OrdinalIgnoreCase) ||
            method.Name.Contains("Current", StringComparison.OrdinalIgnoreCase),
            "business snapshot API must not expose freshness semantics: " + method.Name);
        AssertFalse(
            !method.ReturnType.IsGenericType ||
            method.ReturnType.GetGenericTypeDefinition() != typeof(Task<>) ||
            !method.ReturnType.GetGenericArguments()[0].IsGenericType ||
            method.ReturnType.GetGenericArguments()[0].GetGenericTypeDefinition() != typeof(PublishedGameSnapshot<>),
            "every business data method must return a published snapshot: " + method.Name);
    }

    var runtimeSource = File.ReadAllText(Path.Combine(applicationDirectory, "RoadhogRuntime.cs"));
    foreach (var rawRead in new[] { "_gameApi.Read", "scopedApi.Read", "inventoryApi.Read" })
    {
        AssertFalse(
            runtimeSource.Contains(rawRead, StringComparison.Ordinal),
            "RoadhogRuntime data reads must use IRoadhogSnapshotReader: " + rawRead);
    }

    foreach (var snapshotType in new[]
             {
                 "PlayerSnapshot",
                 "GatherSnapshot",
                 "SkillSnapshot",
                 "WorldObjectSnapshot",
                 "InventoryItemSnapshot",
                 "SummonedPetSnapshot",
                 "SummonedPetRosterSnapshot",
                 "TeamSnapshot",
                 "RadarLiveSnapshot",
                 "ChannelSnapshot"
             })
    {
        AssertFalse(
            runtimeSource.Contains("OperationResult<" + snapshotType, StringComparison.Ordinal),
            "RoadhogRuntime must return official data directly instead of read status for " + snapshotType);
    }

    var servicesSource = File.ReadAllText(
        Path.Combine(directory.FullName, "Roadhog", "Infrastructure", "Composition", "RoadhogServices.cs"));
    AssertFalse(
        servicesSource.Contains("public IRoadhogGameApi", StringComparison.Ordinal),
        "RoadhogServices must not expose the raw game API outside composition");

    var formSource = File.ReadAllText(Path.Combine(directory.FullName, "Roadhog", "Form1.cs"));
    AssertFalse(
        formSource.Contains("_services.GameApi", StringComparison.Ordinal) ||
        formSource.Contains("GameApiReadContext", StringComparison.Ordinal),
        "UI data reads must go through RoadhogRuntime snapshot-backed methods");
    return Task.CompletedTask;
}

static ScriptSettings CreateDiscardScriptSettings(string discardRuleKey, int threshold)
{
    var rules = BagCleanupRuleCatalog.CreateDefaultRules();
    var discardRule = rules.First(rule => rule.Key == discardRuleKey);
    discardRule.Enabled = true;
    discardRule.Action = BagCleanupAction.Discard;
    var settings = CreateScriptSettings();
    settings.Paths.DeathReviveClickX = 680;
    settings.Paths.DeathReviveClickY = 467;
    settings.Maintenance = new MaintenanceScriptSettings
    {
        BagCleanupEnabled = true,
        BagCleanupThreshold = threshold,
        BagCleanupRules = rules,
        BagCleanupDiscardConfirmClickX = 650,
        BagCleanupDiscardConfirmClickY = 470
    };
    return settings;
}

static FakeGameApi CreateSafeDiscardGameApi(int capacity, params InventoryItemSnapshot[] items)
{
    return new FakeGameApi
    {
        TargetEntityId = 0,
        TargetCurrentHp = 0,
        TargetMaxHp = 0,
        TargetName = string.Empty,
        TargetIsTargetingLocalPlayer = false,
        InventoryCapacity = capacity,
        InventoryItems = items,
        WorldObjects = Array.Empty<WorldObjectSnapshot>(),
        InventoryDiscardConfirm = InventoryDiscardConfirmSnapshot.Closed(DateTimeOffset.Now)
    };
}

static Func<int> WireDiscardInputSimulation(
    RecordingKeyboardInput keyboard,
    FakeGameApi gameApi,
    BagCleanupState state,
    bool firstItemUsesSpecialConfirm)
{
    var leftHeld = false;
    var confirming = false;
    var confirmClicks = 0;
    keyboard.AfterPress = key =>
    {
        if (key == "I")
        {
            gameApi.InventoryWindow = CreateInventoryWindow(!gameApi.InventoryWindow.IsOpen, 0.0, 0.0);
        }
    };
    keyboard.AfterMouseDown = button =>
    {
        if (button != RoadhogMouseButton.Left)
        {
            return;
        }

        leftHeld = true;
        confirming = gameApi.InventoryDiscardConfirm.IsOpen;
    };
    keyboard.AfterMove = (x, y) =>
    {
        if (!leftHeld || confirming || state.DiscardTarget is not { } target)
        {
            return;
        }

        var targetId = checked((uint)target.InstanceId);
        var kind = firstItemUsesSpecialConfirm && target.InstanceId == 10
            ? InventoryDiscardConfirmKind.Special
            : InventoryDiscardConfirmKind.Normal;
        gameApi.InventoryDiscardConfirm = new InventoryDiscardConfirmSnapshot(
            true,
            targetId,
            kind,
            kind == InventoryDiscardConfirmKind.Special ? 356 : 336,
            0x1234,
            DateTimeOffset.Now);
    };
    keyboard.AfterMouseUp = button =>
    {
        if (button != RoadhogMouseButton.Left)
        {
            return;
        }

        leftHeld = false;
        if (!confirming || state.DiscardTarget is not { } target)
        {
            confirming = false;
            return;
        }

        confirmClicks++;
        confirming = false;
        if (gameApi.InventoryDiscardConfirm.Kind == InventoryDiscardConfirmKind.Special)
        {
            gameApi.InventoryDiscardConfirm = new InventoryDiscardConfirmSnapshot(
                true,
                checked((uint)target.InstanceId),
                InventoryDiscardConfirmKind.Normal,
                336,
                0x2345,
                DateTimeOffset.Now);
            return;
        }

        gameApi.InventoryItems = gameApi.InventoryItems
            .Where(item => item.InstanceId != target.InstanceId)
            .ToArray();
        gameApi.InventoryDiscardConfirm = InventoryDiscardConfirmSnapshot.Closed(DateTimeOffset.Now);
    };
    return () => confirmClicks;
}

