static Task TestBagCleanupMatcherExcludesNameKeywordsAsync()
{
    var rules = BagCleanupRuleCatalog.CreateDefaultRules();
    rules.First(rule => rule.Key == BagCleanupRuleCatalog.Stigma).Enabled = true;
