static async Task TestAccountConfigPersistsBagCleanupRulesAsync()
{
    var directory = CreateTempDirectory("roadhog-bag-cleanup-");
    try
    {
        var accountPath = Path.Combine(directory, "accounts.json");
        var store = new JsonAccountConfigStore(accountPath);
        var rules = BagCleanupRuleCatalog.CreateDefaultRules();
        rules.First(rule => rule.Key == BagCleanupRuleCatalog.GreenEquipment).Enabled = true;
        rules.First(rule => rule.Key == BagCleanupRuleCatalog.GreenEquipment).Action = BagCleanupAction.Discard;
        rules.First(rule => rule.Key == BagCleanupRuleCatalog.Medicine).Enabled = true;

        var account = new AccountConfig
        {
            AccountName = "account-cleanup",
            ScriptSettings = new ScriptSettings
            {
                Maintenance = new MaintenanceScriptSettings
                {
                    BagCleanupEnabled = true,
                    BagCleanupThreshold = 3,
                    BagCleanupSellItemClickX = 111,
                    BagCleanupSellItemClickY = 222,
                    BagCleanupSellButtonClickX = 333,
                    BagCleanupSellButtonClickY = 444,
                    BagCleanupDiscardConfirmClickX = 555,
                    BagCleanupDiscardConfirmClickY = 666,
                    BagCleanupItemCoordinateMode = BagCleanupItemCoordinateMode.WindowRectRelativeExperimental,
                    DpMaintenanceRules = new List<DpMaintenanceRuleConfig>
                    {
                        new()
                        {
                            RequiredDp = 4000,
                            Key = "NumPad9",
                            SkillId = 1787,
                            SkillName = "Pet DP Buff"
                        }
                    },
                    MpMaintenanceRules = new List<MaintenanceKeyRuleConfig>
                    {
                        new()
                        {
                            BelowPercent = 60,
                            ActionType = MaintenanceRuleActionType.Potion,
                            Key = "NumPad2",
                            RunTiming = MaintenanceRuleRunTiming.AfterCombat
                        }
                    },
                    BagCleanupRules = rules,
                    BagCleanupExcludedItemNames = new List<string> { "protected-item" },
                    BagCleanupDiscardItemNameKeywords = new List<string> { "discard-item" }
                }
            }
        };

        var save = await store.UpsertAsync(account).ConfigureAwait(false);
        AssertFalse(!save.Success, "account save should succeed");

        var text = await File.ReadAllTextAsync(accountPath).ConfigureAwait(false);
        AssertFalse(!text.Contains("\"BagCleanupEnabled\": true", StringComparison.Ordinal), "account config should contain bag cleanup enabled");
        AssertFalse(!text.Contains("\"BagCleanupRules\"", StringComparison.Ordinal), "account config should contain bag cleanup rules");
        AssertFalse(!text.Contains("\"BagCleanupDiscardItemNameKeywords\"", StringComparison.Ordinal), "account config should contain bag cleanup blacklist fallback");
        AssertFalse(!text.Contains("\"BagCleanupSellItemClickX\": 111", StringComparison.Ordinal), "account config should contain sell item click x");
        AssertFalse(!text.Contains("\"BagCleanupSellItemClickY\": 222", StringComparison.Ordinal), "account config should contain sell item click y");
        AssertFalse(!text.Contains("\"BagCleanupSellButtonClickX\": 333", StringComparison.Ordinal), "account config should contain sell button click x");
        AssertFalse(!text.Contains("\"BagCleanupSellButtonClickY\": 444", StringComparison.Ordinal), "account config should contain sell button click y");
        AssertFalse(!text.Contains("\"BagCleanupDiscardConfirmClickX\": 555", StringComparison.Ordinal), "account config should contain discard confirm click x");
        AssertFalse(!text.Contains("\"BagCleanupDiscardConfirmClickY\": 666", StringComparison.Ordinal), "account config should contain discard confirm click y");
        AssertFalse(!text.Contains("\"DpMaintenanceRules\"", StringComparison.Ordinal), "account config should contain dp maintenance rules");
        AssertFalse(!text.Contains("\"RequiredDp\": 4000", StringComparison.Ordinal), "account config should contain dp requirement");
        AssertFalse(!text.Contains("\"Key\": \"NumPad9\"", StringComparison.Ordinal), "account config should contain dp maintenance key");
        AssertFalse(!text.Contains("\"ActionType\": \"Potion\"", StringComparison.Ordinal), "account config should contain potion maintenance type");
        AssertFalse(
            !text.Contains(
                "\"BagCleanupItemCoordinateMode\": \"WindowRectRelativeExperimental\"",
                StringComparison.Ordinal),
            "account config should contain bag item coordinate mode");
        AssertFalse(!text.Contains("\"Key\": \"equipment.green\"", StringComparison.Ordinal), "bag cleanup rule key should be persisted");
        AssertFalse(!text.Contains("\"Category\": \"equipment\"", StringComparison.Ordinal), "bag cleanup category should be persisted");
        AssertFalse(!text.Contains("\"Quality\": \"green\"", StringComparison.Ordinal), "bag cleanup quality should be persisted");
        AssertFalse(!text.Contains("\"Key\": \"equipment.white\"", StringComparison.Ordinal), "white equipment cleanup rule key should be persisted");
        AssertFalse(!text.Contains("\"Quality\": \"white\"", StringComparison.Ordinal), "white equipment cleanup quality should be persisted");
        AssertFalse(!text.Contains("\"weapon\"", StringComparison.Ordinal), "bag cleanup item kind should be persisted");
        AssertFalse(!text.Contains("\"accessory\"", StringComparison.Ordinal), "bag cleanup accessory kind should be persisted");
        AssertFalse(!text.Contains("\"Action\": \"Discard\"", StringComparison.Ordinal), "bag cleanup action should be persisted");

        var load = await store.LoadAllAsync().ConfigureAwait(false);
        AssertFalse(!load.Success, "account config should load");
        var maintenance = load.Value?[0].ScriptSettings?.Maintenance;
        AssertFalse(maintenance?.BagCleanupEnabled != true, "loaded bag cleanup enabled");
        AssertEqual(111, maintenance?.BagCleanupSellItemClickX ?? 0, "loaded sell item click x");
        AssertEqual(222, maintenance?.BagCleanupSellItemClickY ?? 0, "loaded sell item click y");
        AssertEqual(333, maintenance?.BagCleanupSellButtonClickX ?? 0, "loaded sell button click x");
        AssertEqual(444, maintenance?.BagCleanupSellButtonClickY ?? 0, "loaded sell button click y");
        AssertEqual(555, maintenance?.BagCleanupDiscardConfirmClickX ?? 0, "loaded discard confirm click x");
        AssertEqual(666, maintenance?.BagCleanupDiscardConfirmClickY ?? 0, "loaded discard confirm click y");
        AssertSequence(new[] { "protected-item" }, maintenance?.BagCleanupExcludedItemNames.ToArray() ?? Array.Empty<string>(), "loaded bag cleanup whitelist fallback");
        AssertSequence(new[] { "discard-item" }, maintenance?.BagCleanupDiscardItemNameKeywords.ToArray() ?? Array.Empty<string>(), "loaded bag cleanup blacklist fallback");
        AssertEqual(
            BagCleanupItemCoordinateMode.WindowRectRelativeExperimental,
            maintenance?.BagCleanupItemCoordinateMode ?? BagCleanupItemCoordinateMode.LegacyNormalizedTopLeft,
            "loaded bag item coordinate mode");
        AssertEqual(1, maintenance?.DpMaintenanceRules.Count ?? 0, "loaded dp maintenance rule count");
        AssertEqual(4000, maintenance?.DpMaintenanceRules[0].RequiredDp ?? 0, "loaded dp requirement");
        AssertEqual("NumPad9", maintenance?.DpMaintenanceRules[0].Key ?? string.Empty, "loaded dp maintenance key");
        AssertEqual(1, maintenance?.MpMaintenanceRules.Count ?? 0, "loaded mp maintenance rule count");
        AssertEqual(MaintenanceRuleActionType.Potion, maintenance?.MpMaintenanceRules[0].ActionType ?? MaintenanceRuleActionType.Skill, "loaded mp maintenance action type");
        AssertEqual(MaintenanceRuleRunTiming.AfterCombat, maintenance?.MpMaintenanceRules[0].RunTiming ?? MaintenanceRuleRunTiming.Always, "loaded mp maintenance timing");
        var loadedRules = BagCleanupRuleCatalog.MergeWithDefaults(load.Value?[0].ScriptSettings?.Maintenance.BagCleanupRules);
        var greenEquipment = loadedRules.First(rule => rule.Key == BagCleanupRuleCatalog.GreenEquipment);
        AssertFalse(!greenEquipment.Enabled, "green equipment cleanup should remain enabled");
        AssertEqual(BagCleanupAction.Discard, greenEquipment.Action, "green equipment cleanup action");
        AssertEqual("equipment", greenEquipment.Category, "green equipment category");
        AssertEqual("green", greenEquipment.Quality, "green equipment quality");
        AssertFalse(!greenEquipment.ItemKinds.Contains("accessory"), "green equipment map should include accessories");
        var whiteEquipment = loadedRules.First(rule => rule.Key == BagCleanupRuleCatalog.WhiteEquipment);
        AssertFalse(whiteEquipment.Enabled, "white equipment cleanup should default disabled");
        AssertEqual("equipment", whiteEquipment.Category, "white equipment category");
        AssertEqual("white", whiteEquipment.Quality, "white equipment quality");
        AssertFalse(!whiteEquipment.ItemKinds.Contains("weapon"), "white equipment map should include weapons");
        AssertFalse(!whiteEquipment.ItemKinds.Contains("armor"), "white equipment map should include armor");
        AssertFalse(!whiteEquipment.ItemKinds.Contains("accessory"), "white equipment map should include accessories");

        var medicine = loadedRules.First(rule => rule.Key == BagCleanupRuleCatalog.Medicine);
        AssertFalse(!medicine.Enabled, "medicine cleanup should remain enabled");
        AssertEqual(BagCleanupAction.Sell, medicine.Action, "medicine cleanup default action");
        AssertFalse(!medicine.ItemKinds.Contains("remedy"), "medicine map should include remedies");
    }
    finally
    {
        DeleteDirectoryIfExists(directory);
    }
}

static Task TestBagCleanupDiscardConfirmPointUiAsync()
{
    var settings = CreateScriptSettings();
    settings.Maintenance.BagCleanupDiscardConfirmClickX = 555;
    settings.Maintenance.BagCleanupDiscardConfirmClickY = 666;
    var configStore = new InMemoryAccountConfigStore(new AccountConfig
    {
        AccountName = "account1",
        ScriptSettings = settings
    });

    using var form = CreateAccountSettingsFormForTestsWithStore(configStore);
    SetComboSelectedIndexForTest(form, "settingsTabs", 5);
    form.Show();
    System.Windows.Forms.Application.DoEvents();

    AssertEqual(
        "555,666",
        GetTextBoxTextForTest(form, "bagCleanupDiscardConfirmPointTextBox"),
        "configured discard confirm point should load into cleanup ui");
    var moveButton = FindNamedControlForTest(form, "bagCleanupDiscardConfirmTestMoveButton");
    AssertEqual("测试移动", moveButton.Text, "discard confirm point should expose a move-only test button");
    AssertFalse(!moveButton.Visible, "discard confirm move test button should be visible on cleanup tab");

    System.Windows.Forms.Control? ancestor = moveButton.Parent;
    while (ancestor is not null && ancestor is not System.Windows.Forms.TabPage)
    {
        ancestor = ancestor.Parent;
    }

    AssertEqual("清包", ancestor?.Text ?? string.Empty, "discard confirm controls should belong to cleanup tab");

    SetTextBoxTextForTest(form, "bagCleanupDiscardConfirmPointTextBox", "777,888");
    var saved = InvokeSaveCurrentSettingsForTest(form, out var error);
    AssertFalse(!saved, "discard confirm point ui save failed: " + error);

    var persisted = configStore
        .LoadAllAsync()
        .GetAwaiter()
        .GetResult()
        .Value?
        .Single()
        .ScriptSettings?
        .Maintenance;
    AssertEqual(777, persisted?.BagCleanupDiscardConfirmClickX ?? 0, "saved discard confirm click x");
    AssertEqual(888, persisted?.BagCleanupDiscardConfirmClickY ?? 0, "saved discard confirm click y");
    return Task.CompletedTask;
}

static Task TestBagCleanupNameListUiAutoSavesAndRollsBackAsync()
{
    var settings = CreateScriptSettings();
    settings.Maintenance.BagCleanupExcludedItemNames = new List<string> { "profile-only" };
    var configStore = new InMemoryAccountConfigStore(new AccountConfig
    {
        AccountName = "account1",
        ScriptSettings = settings
    });
    var nameListStore = new InMemoryBagCleanupNameListStore(new BagCleanupNameListsDocument
    {
        Whitelist = new List<string> { "shared-keep" },
        Blacklist = new List<string> { "shared-discard" }
    });

    using var form = CreateAccountSettingsFormForTestsWithStore(
        configStore,
        bagCleanupNameListStore: nameListStore);
    var combo = (System.Windows.Forms.Control)GetPrivateFieldForTest(form, "bagCleanupInventoryCombo");
    var listBox = (System.Windows.Forms.ListBox)GetPrivateFieldForTest(form, "bagCleanupExcludedItemListBox");
    var blacklistRadio = (System.Windows.Forms.RadioButton)GetPrivateFieldForTest(form, "bagCleanupBlacklistRadio");
    var addButton = (System.Windows.Forms.Button)GetPrivateFieldForTest(form, "bagCleanupAddNameButton");

    AssertSequence(new[] { "shared-keep" }, listBox.Items.Cast<string>().ToArray(), "shared whitelist should override profile list in ui");
    combo.Text = "new-keep";
    InvokePrivateTaskForTest(form, "AddSelectedBagCleanupNameAsync");
    AssertEqual(1, nameListStore.SaveCount, "adding whitelist should auto-save once");
    AssertSequence(new[] { "shared-keep", "new-keep" }, nameListStore.Document.Whitelist.ToArray(), "whitelist add should persist");
    AssertSequence(new[] { "shared-discard" }, nameListStore.Document.Blacklist.ToArray(), "whitelist add must preserve blacklist");

    blacklistRadio.Checked = true;
    AssertEqual("加入处理（丢弃）", addButton.Text, "blacklist radio should change add action text");
    AssertSequence(new[] { "shared-discard" }, listBox.Items.Cast<string>().ToArray(), "blacklist radio should show blacklist");
    combo.Text = "new-discard";
    InvokePrivateTaskForTest(form, "AddSelectedBagCleanupNameAsync");
    AssertEqual(2, nameListStore.SaveCount, "adding blacklist should auto-save once");
    AssertSequence(new[] { "shared-discard", "new-discard" }, nameListStore.Document.Blacklist.ToArray(), "blacklist add should persist");
    AssertSequence(new[] { "shared-keep", "new-keep" }, nameListStore.Document.Whitelist.ToArray(), "blacklist add must preserve whitelist");

    InvokePrivateTaskForTest(form, "RemoveSelectedBagCleanupNameAsync");
    AssertEqual(3, nameListStore.SaveCount, "removing blacklist should auto-save");
    AssertSequence(new[] { "shared-discard" }, nameListStore.Document.Blacklist.ToArray(), "selected blacklist entry should be removed");

    InvokePrivateTaskForTest(form, "ClearSelectedBagCleanupNameListAsync");
    AssertEqual(4, nameListStore.SaveCount, "clearing blacklist should auto-save");
    AssertEqual(0, nameListStore.Document.Blacklist.Count, "blacklist clear should persist empty array");
    AssertSequence(new[] { "shared-keep", "new-keep" }, nameListStore.Document.Whitelist.ToArray(), "blacklist clear must preserve whitelist");

    nameListStore.FailSaves = true;
    combo.Text = "must-roll-back";
    InvokePrivateTaskForTest(form, "AddSelectedBagCleanupNameAsync");
    var capturedBlacklist = (List<string>)(InvokePrivateMethodForTest(form, "CaptureBagCleanupDiscardItemList") ?? new List<string>());
    AssertEqual(0, capturedBlacklist.Count, "failed save should roll back blacklist editor");
    AssertEqual(0, nameListStore.Document.Blacklist.Count, "failed save must not mutate persisted blacklist");

    nameListStore.FailSaves = false;
    nameListStore.BlockSaves = true;
    combo.Text = "slow-discard";
    var slowSaveTask = InvokePrivateMethodForTest(form, "AddSelectedBagCleanupNameAsync") as Task;
    AssertFalse(slowSaveTask is null || slowSaveTask.IsCompleted, "delayed save should keep the first mutation in flight");
    var removeButton = (System.Windows.Forms.Button)GetPrivateFieldForTest(form, "bagCleanupRemoveNameButton");
    var clearButton = (System.Windows.Forms.Button)GetPrivateFieldForTest(form, "bagCleanupClearNamesButton");
    AssertFalse(addButton.Enabled, "add should be disabled while a name-list save is in flight");
    AssertFalse(removeButton.Enabled, "remove should be disabled while a name-list save is in flight");
    AssertFalse(clearButton.Enabled, "clear should be disabled while a name-list save is in flight");
    AssertFalse(blacklistRadio.Enabled, "list switching should be disabled while a name-list save is in flight");

    combo.Text = "must-not-overlap";
    var overlappingTask = InvokePrivateMethodForTest(form, "AddSelectedBagCleanupNameAsync") as Task;
    AssertFalse(overlappingTask is null || !overlappingTask.IsCompleted, "overlapping mutation should be ignored immediately");
    AssertEqual(6, nameListStore.SaveCount, "overlapping mutation must not start another save");

    nameListStore.CompletePendingSave();
    slowSaveTask!.GetAwaiter().GetResult();
    AssertFalse(!addButton.Enabled || !removeButton.Enabled || !clearButton.Enabled, "mutation buttons should be restored after save");
    AssertFalse(!blacklistRadio.Enabled, "list switching should be restored after save");
    AssertSequence(new[] { "slow-discard" }, nameListStore.Document.Blacklist.ToArray(), "only the first in-flight mutation should persist");
    return Task.CompletedTask;
}

static async Task TestRevivePathAggressiveClearRadiusDefaultsCloneJsonAndUiAsync()
{
    var defaults = new PathScriptSettings();
    AssertEqual(
        PathScriptSettings.DefaultRevivePathAggressiveClearRadius,
        defaults.RevivePathAggressiveClearRadius,
        "revive path aggressive clear radius should default to ten meters");

    defaults.RevivePathAggressiveClearRadius = 17.5D;
    AssertEqual(
        17.5D,
        defaults.Clone().RevivePathAggressiveClearRadius,
        "path settings clone should preserve revive path aggressive clear radius");

    var directory = CreateTempDirectory("roadhog-revive-clear-radius-");
    try
    {
        var accountPath = Path.Combine(directory, "accounts.json");
        var jsonStore = new JsonAccountConfigStore(accountPath);
        var save = await jsonStore.UpsertAsync(new AccountConfig
        {
            AccountName = "revive-clear-radius-json",
            ScriptSettings = new ScriptSettings
            {
                Paths = defaults
            }
        }).ConfigureAwait(false);
        AssertFalse(!save.Success, "revive path clear radius json save should succeed");

        var load = await jsonStore.LoadAllAsync().ConfigureAwait(false);
        AssertFalse(!load.Success, "revive path clear radius json load should succeed");
        AssertEqual(
            17.5D,
            load.Value?.Single().ScriptSettings?.Paths.RevivePathAggressiveClearRadius ?? 0.0D,
            "revive path aggressive clear radius should round-trip through account json");
    }
    finally
    {
        DeleteDirectoryIfExists(directory);
    }

    Exception? failure = null;
    var thread = new Thread(() =>
    {
        try
        {
            var configured = CreateScriptSettings();
            configured.Paths.RevivePathAggressiveClearRadius = 18.5D;
            var configStore = new InMemoryAccountConfigStore(new AccountConfig
            {
                AccountName = "account1",
                ScriptSettings = configured
            });

            using var form = CreateAccountSettingsFormForTestsWithStore(configStore);
            SetComboSelectedIndexForTest(form, "settingsTabs", 1);
            var pathTabs = (System.Windows.Forms.TabControl)FindNamedControlForTest(form, "pathTabs");
            pathTabs.SelectedIndex = 0;
            form.Show();
            System.Windows.Forms.Application.DoEvents();

            AssertEqual(
                "18.5",
                GetTextBoxTextForTest(form, "revivePathAggressiveClearRadiusTextBox"),
                "configured revive path aggressive clear radius should load into UI");
            AssertFalse(
                !GetControlVisibleForTest(form, "revivePathAggressiveClearRadiusTextBox"),
                "revive path aggressive clear radius should be visible in expanded advanced settings");

            System.Windows.Forms.Control? ancestor = FindNamedControlForTest(
                form,
                "revivePathAggressiveClearRadiusTextBox").Parent;
            while (ancestor is not null && ancestor is not System.Windows.Forms.TabPage)
            {
                ancestor = ancestor.Parent;
            }

            AssertEqual(
                "复活路径",
                ancestor?.Text ?? string.Empty,
                "revive path aggressive clear radius should belong to the revive path tab");

            SetTextBoxTextForTest(form, "revivePathAggressiveClearRadiusTextBox", "12.5");
            var saved = InvokeSaveCurrentSettingsForTest(form, out var error);
            AssertFalse(!saved, "revive path aggressive clear radius ui save failed: " + error);

            var savedSettings = configStore
                .LoadAllAsync()
                .GetAwaiter()
                .GetResult()
                .Value?
                .Single()
                .ScriptSettings;
            AssertEqual(
                12.5D,
                savedSettings?.Paths.RevivePathAggressiveClearRadius ?? 0.0D,
                "revive path aggressive clear radius should persist from UI");
        }
        catch (Exception ex)
        {
            failure = ex;
        }
    });

    thread.SetApartmentState(ApartmentState.STA);
    thread.Start();
    thread.Join();
    if (failure is not null)
    {
        throw failure;
    }
}

