static async Task TestAccountConfigPersistsStationaryCombatPositionAsync()
{
    var directory = CreateTempDirectory("roadhog-stationary-combat-");
    try
    {
        var accountPath = Path.Combine(directory, "accounts.json");
        var store = new JsonAccountConfigStore(accountPath);
        var account = new AccountConfig
        {
            AccountName = "account-stationary",
            ScriptSettings = new ScriptSettings
            {
                MainMode = AccountMainMode.CustomCombat,
                CombatMode = AccountCombatMode.Stationary,
                Combat = new CombatScriptSettings
                {
                    EnableLoot = true,
                    PreferAggressiveMonsters = true,
                    SmartPreAimEnabled = true,
                    SmartPreAimUseFightTargetPosition = true,
                    ReturnHomeWhenNoTarget = false,
                    SitWhenNoTargetAtHome = true,
                    HasStationaryCombatPosition = true,
                    StationaryCombatX = 1307.758D,
                    StationaryCombatY = 2844.230D,
                    StationaryCombatZ = 259.832D,
                    StationaryCombatRadius = 42.5D,
                    PathCombatRadius = 37.5D,
                    PathFollowReachDistance = 6.5D,
                    CameraYawPixelsPerDegree = 11.5D,
                    CameraPitchPixelsPerDegree = 13.25D
                }
            }
        };

        var save = await store.UpsertAsync(account).ConfigureAwait(false);
        AssertFalse(!save.Success, "stationary combat account save should succeed");

        var load = await store.LoadAllAsync().ConfigureAwait(false);
        AssertFalse(!load.Success, "stationary combat account should load");
        var combat = load.Value?[0].ScriptSettings?.Combat;
        AssertFalse(combat is null, "combat settings should load");
        AssertFalse(!combat!.HasStationaryCombatPosition, "stationary combat position flag should persist");
        AssertEqual(1307.758D, combat.StationaryCombatX, "stationary x");
        AssertEqual(2844.230D, combat.StationaryCombatY, "stationary y");
        AssertEqual(259.832D, combat.StationaryCombatZ, "stationary z");
        AssertEqual(42.5D, combat.StationaryCombatRadius, "stationary radius");
        AssertEqual(37.5D, combat.PathCombatRadius, "path radius");
        AssertEqual(6.5D, combat.PathFollowReachDistance, "path follow precision");
        AssertEqual(11.5D, combat.CameraYawPixelsPerDegree, "camera yaw pixels per degree");
        AssertEqual(13.25D, combat.CameraPitchPixelsPerDegree, "camera pitch pixels per degree");
        AssertFalse(!combat.PreferAggressiveMonsters, "prefer aggressive monsters should persist");
        AssertFalse(!combat.SmartPreAimEnabled, "smart pre-aim should persist");
        AssertFalse(!combat.SmartPreAimUseFightTargetPosition, "fight-target smart pre-aim origin should persist");
        AssertFalse(combat.ReturnHomeWhenNoTarget, "return home when no target should persist");
        AssertFalse(!combat.SitWhenNoTargetAtHome, "sit when no target at home should persist");

        var clone = account.ScriptSettings.Combat.Clone();
        AssertFalse(!clone.HasStationaryCombatPosition, "stationary combat position flag should clone");
        AssertEqual(1307.758D, clone.StationaryCombatX, "cloned stationary x");
        AssertEqual(42.5D, clone.StationaryCombatRadius, "cloned stationary radius");
        AssertEqual(37.5D, clone.PathCombatRadius, "cloned path radius");
        AssertEqual(6.5D, clone.PathFollowReachDistance, "cloned path follow precision");
        AssertEqual(11.5D, clone.CameraYawPixelsPerDegree, "cloned camera yaw pixels per degree");
        AssertEqual(13.25D, clone.CameraPitchPixelsPerDegree, "cloned camera pitch pixels per degree");
        AssertFalse(!clone.PreferAggressiveMonsters, "prefer aggressive monsters should clone");
        AssertFalse(!clone.SmartPreAimEnabled, "smart pre-aim should clone");
        AssertFalse(!clone.SmartPreAimUseFightTargetPosition, "fight-target smart pre-aim origin should clone");
        AssertFalse(clone.ReturnHomeWhenNoTarget, "return home when no target should clone");
        AssertFalse(!clone.SitWhenNoTargetAtHome, "sit when no target at home should clone");
    }
    finally
    {
        DeleteDirectoryIfExists(directory);
    }
}

static Task TestStationaryTargetSelectorAsync()
{
    var player = new Vector3Snapshot(0, 0, 0);
    var home = new Vector3Snapshot(0, 0, 0);
    var objects = new[]
    {
        new WorldObjectSnapshot(10, 10, "npc", "npc", new Vector3Snapshot(1, 0, 0), 1, 100, 100),
        new WorldObjectSnapshot(11, 11, "dead", "monster", new Vector3Snapshot(2, 0, 0), 2, 0, 100),
        new WorldObjectSnapshot(12, 12, "outside", "monster", new Vector3Snapshot(40, 0, 0), 40, 100, 100),
        new WorldObjectSnapshot(13, 13, "farther", "monster", new Vector3Snapshot(8, 0, 0), 8, 100, 100),
        new WorldObjectSnapshot(14, 14, "nearest", "monster", new Vector3Snapshot(5, 0, 0), 5, 100, 100)
    };

    var selected = StationaryCombatTargetSelector.SelectNearest(objects, player, home, 30);

    AssertEqual((ushort)14, selected?.EntityId ?? 0, "nearest selectable monster");

    var activeSelected = StationaryCombatTargetSelector.SelectNearest(
        new[]
        {
            new WorldObjectSnapshot(20, 20, "passive-near", "monster", new Vector3Snapshot(3, 0, 0), 3, 100, 100, AggressiveKnown: true, IsAggressiveToPlayer: false),
            new WorldObjectSnapshot(21, 21, "active-far", "monster", new Vector3Snapshot(8, 0, 0), 8, 100, 100, AggressiveKnown: true, IsAggressiveToPlayer: true)
        },
        player,
        home,
        30,
        preferAggressiveMonsters: true);

    AssertEqual((ushort)21, activeSelected?.EntityId ?? 0, "aggressive monster should outrank nearer passive monster");
    return Task.CompletedTask;
}

static Task TestSmartPreAimSelectorScoresThreatsAndAggressiveSettingAsync()
{
    var player = new Vector3Snapshot(0, 0, 0);
    var home = new Vector3Snapshot(0, 0, 0);
    const uint localServerObjectId = 9000;
    var objects = new[]
    {
        new WorldObjectSnapshot(10, 1010, "current", "monster", new Vector3Snapshot(1, 0, 0), 1, 100, 100),
        new WorldObjectSnapshot(11, 1011, "passive-near", "monster", new Vector3Snapshot(3, 0, 0), 3, 100, 100, AggressiveKnown: true),
        new WorldObjectSnapshot(12, 1012, "active-far", "monster", new Vector3Snapshot(8, 0, 0), 8, 100, 100, AggressiveKnown: true, IsAggressiveToPlayer: true),
        new WorldObjectSnapshot(13, 1013, "local-threat", "monster", new Vector3Snapshot(12, 0, 0), 12, 100, 100, TargetServerObjectId: localServerObjectId)
    };

    var threatSelected = NextTargetPreAimSelector.Select(
        objects,
        player,
        home,
        30,
        currentTargetEntityId: 10,
        currentTargetServerObjectId: 1010,
        localSideServerObjectId: localServerObjectId,
        localSidePetServerObjectId: 0,
        allowClaimedByOther: false,
        preferAggressiveMonsters: true);

    AssertEqual((ushort)13, threatSelected?.Target.EntityId ?? 0, "local-side threat should outrank aggressive and distance");
    AssertEqual(4, threatSelected?.PriorityTier ?? 0, "local-side threat priority tier");

    var teamThreat = new WorldObjectSnapshot(
        14,
        1014,
        "team-threat",
        "monster",
        new Vector3Snapshot(10, 0, 0),
        10,
        100,
        100,
        TargetServerObjectId: 8000);
    var teamThreatSelected = NextTargetPreAimSelector.Select(
        new[] { objects[0], objects[1], objects[2], teamThreat },
        player,
        home,
        30,
        currentTargetEntityId: 10,
        currentTargetServerObjectId: 1010,
        localSideServerObjectId: localServerObjectId,
        localSidePetServerObjectId: 0,
        allowClaimedByOther: false,
        preferAggressiveMonsters: true,
        teamSideServerObjectIds: new HashSet<uint> { 8000 });

    AssertEqual(teamThreat.EntityId, teamThreatSelected?.Target.EntityId ?? 0, "team-side threat should remain eligible when contesting is disabled");
    AssertEqual(3, teamThreatSelected?.PriorityTier ?? 0, "team-side threat priority tier");
    AssertFalse(teamThreatSelected?.IsTargetingTeamSide != true, "team-side threat should be identified explicitly");

    var localBeforeTeam = NextTargetPreAimSelector.Select(
        objects.Append(teamThreat),
        player,
        home,
        30,
        currentTargetEntityId: 10,
        currentTargetServerObjectId: 1010,
        localSideServerObjectId: localServerObjectId,
        localSidePetServerObjectId: 0,
        allowClaimedByOther: false,
        preferAggressiveMonsters: true,
        teamSideServerObjectIds: new HashSet<uint> { 8000 });

    AssertEqual((ushort)13, localBeforeTeam?.Target.EntityId ?? 0, "local-side threat should outrank a simultaneous team-side threat");

    var withoutThreat = objects.Where(target => target.EntityId != 13).ToArray();
    var normalSelected = NextTargetPreAimSelector.Select(
        withoutThreat,
        player,
        home,
        30,
        currentTargetEntityId: 10,
        currentTargetServerObjectId: 1010,
        localSideServerObjectId: localServerObjectId,
        localSidePetServerObjectId: 0,
        allowClaimedByOther: false,
        preferAggressiveMonsters: false);

    AssertEqual((ushort)11, normalSelected?.Target.EntityId ?? 0, "without aggressive preference nearest ordinary target should win");

    var aggressiveSelected = NextTargetPreAimSelector.Select(
        withoutThreat,
        player,
        home,
        30,
        currentTargetEntityId: 10,
        currentTargetServerObjectId: 1010,
        localSideServerObjectId: localServerObjectId,
        localSidePetServerObjectId: 0,
        allowClaimedByOther: false,
        preferAggressiveMonsters: true);

    AssertEqual((ushort)12, aggressiveSelected?.Target.EntityId ?? 0, "aggressive preference should follow configured setting");
    AssertEqual(2, aggressiveSelected?.PriorityTier ?? 0, "aggressive priority tier");
    return Task.CompletedTask;
}

static Task TestSmartPreAimSupportsFightTargetDistanceOriginAsync()
{
    var player = new Vector3Snapshot(0, 0, 0);
    var home = new Vector3Snapshot(0, 0, 0);
    var fightTargetPosition = new Vector3Snapshot(10, 0, 0);
    var currentTarget = new WorldObjectSnapshot(40, 4040, "current", "monster", fightTargetPosition, 10, 100, 100);
    var nearPlayer = new WorldObjectSnapshot(41, 4041, "near-player", "monster", new Vector3Snapshot(2, 0, 0), 2, 100, 100);
    var nearFightTarget = new WorldObjectSnapshot(42, 4042, "near-fight-target", "monster", new Vector3Snapshot(11, 0, 0), 11, 100, 100);
    var objects = new[] { currentTarget, nearPlayer, nearFightTarget };

    var playerOriginSelection = NextTargetPreAimSelector.Select(
        objects,
        player,
        home,
        30,
        currentTargetEntityId: currentTarget.EntityId,
        currentTargetServerObjectId: currentTarget.ServerObjectId,
        localSideServerObjectId: 0,
        localSidePetServerObjectId: 0,
        allowClaimedByOther: false,
        preferAggressiveMonsters: false);
    var fightTargetOriginSelection = NextTargetPreAimSelector.Select(
        objects,
        fightTargetPosition,
        home,
        30,
        currentTargetEntityId: currentTarget.EntityId,
        currentTargetServerObjectId: currentTarget.ServerObjectId,
        localSideServerObjectId: 0,
        localSidePetServerObjectId: 0,
        allowClaimedByOther: false,
        preferAggressiveMonsters: false);

    AssertEqual(nearPlayer.EntityId, playerOriginSelection?.Target.EntityId ?? 0, "player origin should keep the existing nearest-target behavior");
    AssertEqual(nearFightTarget.EntityId, fightTargetOriginSelection?.Target.EntityId ?? 0, "fight-target origin should select the target nearest the current fight");

    var settings = CreateScriptSettings();
    settings.MainMode = AccountMainMode.CustomCombat;
    settings.CombatMode = AccountCombatMode.Stationary;
    settings.Combat = new CombatScriptSettings
    {
        SmartPreAimEnabled = true,
        SmartPreAimUseFightTargetPosition = true
    };
    var context = CreateContext(settings, new FakeGameApi(), new InMemoryRoadhogLogger());
    var state = new StationaryCombatState();
    state.NextTargetPreAim.TargetEntityId = nearFightTarget.EntityId;
    state.NextTargetPreAim.TargetServerObjectId = nearFightTarget.ServerObjectId;
    state.NextTargetPreAim.TargetPosition = nearFightTarget.Position;
    state.NextTargetPreAim.FightTargetPosition = fightTargetPosition;

    var pendingOriginMethod = typeof(StationaryCombatController).GetMethod(
        "ResolvePendingNextTargetSelectionOrigin",
        System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);
    var scanOriginMethod = typeof(StationaryCombatController).GetMethod(
        "ResolveSmartPreAimDistanceOrigin",
        System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);
    AssertFalse(pendingOriginMethod is null, "normal next-target origin helper should exist");
    AssertFalse(scanOriginMethod is null, "smart pre-aim scan origin helper should exist");

    var pendingOrigin = (Vector3Snapshot)pendingOriginMethod!.Invoke(
        null,
        new object[] { context, state, player })!;
    var normalSelected = StationaryCombatTargetSelector.SelectNearest(
        new[] { nearPlayer, nearFightTarget },
        pendingOrigin,
        home,
        30);
    AssertEqual(nearFightTarget.EntityId, normalSelected?.EntityId ?? 0, "normal next-target selection should reuse the pre-aim fight-target origin");

    var movedFightTarget = currentTarget with { Position = new Vector3Snapshot(14, 0, 0) };
    var refreshedOrigin = (Vector3Snapshot)scanOriginMethod!.Invoke(
        null,
        new object[]
        {
            context,
            state,
            new[] { movedFightTarget, nearPlayer, nearFightTarget },
            player,
            currentTarget.EntityId,
            currentTarget.ServerObjectId
        })!;
    AssertEqual(14D, refreshedOrigin.X, "live fight-target position should refresh from the batch world snapshot");

    var cachedOrigin = (Vector3Snapshot)scanOriginMethod.Invoke(
        null,
        new object[]
        {
            context,
            state,
            new[] { nearPlayer, nearFightTarget },
            player,
            currentTarget.EntityId,
            currentTarget.ServerObjectId
        })!;
    AssertEqual(14D, cachedOrigin.X, "last fight-target position should remain after the target disappears during loot");

    state.NextTargetPreAim.FightTargetPosition = null;
    var fallbackOrigin = (Vector3Snapshot)scanOriginMethod.Invoke(
        null,
        new object[]
        {
            context,
            state,
            new[] { nearPlayer, nearFightTarget },
            player,
            currentTarget.EntityId,
            currentTarget.ServerObjectId
        })!;
    AssertEqual(player.X, fallbackOrigin.X, "missing fight-target coordinates should fall back to player position");
    AssertEqual(player.Y, fallbackOrigin.Y, "missing fight-target coordinates should fall back to player position");

    settings.Combat.SmartPreAimUseFightTargetPosition = false;
    state.NextTargetPreAim.FightTargetPosition = fightTargetPosition;
    var disabledOrigin = (Vector3Snapshot)scanOriginMethod.Invoke(
        null,
        new object[]
        {
            context,
            state,
            new[] { movedFightTarget, nearPlayer, nearFightTarget },
            player,
            currentTarget.EntityId,
            currentTarget.ServerObjectId
        })!;
    AssertEqual(player.X, disabledOrigin.X, "disabled fight-target origin should preserve player-based selection");
    AssertEqual(player.Y, disabledOrigin.Y, "disabled fight-target origin should preserve player-based selection");
    return Task.CompletedTask;
}

static Task TestSmartPreAimSelectorKeepsStableTargetAsync()
{
    var player = new Vector3Snapshot(0, 0, 0);
    var home = new Vector3Snapshot(0, 0, 0);
    var now = new DateTimeOffset(2026, 8, 7, 12, 0, 0, TimeSpan.Zero);
    var currentTarget = new WorldObjectSnapshot(20, 2020, "stable", "monster", new Vector3Snapshot(7, 0, 0), 7, 100, 100);
    var slightlyCloser = new WorldObjectSnapshot(21, 2021, "slightly-closer", "monster", new Vector3Snapshot(6, 0, 0), 6, 100, 100);
    var muchCloser = new WorldObjectSnapshot(22, 2022, "much-closer", "monster", new Vector3Snapshot(3, 0, 0), 3, 100, 100);
    var currentSelection = new NextTargetPreAimSelection(
        currentTarget,
        1,
        7,
        IsTargetingLocalSide: false,
        IsTargetingTeamSide: false,
        IsAggressivePriority: false,
        now,
        "current");

    var held = NextTargetPreAimSelector.Select(
        new[] { currentTarget, slightlyCloser },
        player,
        home,
        30,
        currentTargetEntityId: 99,
        currentTargetServerObjectId: 9999,
        localSideServerObjectId: 0,
        localSidePetServerObjectId: 0,
        allowClaimedByOther: false,
        preferAggressiveMonsters: false,
        currentSelection: currentSelection,
        now: now.AddMilliseconds(200),
        minimumHold: TimeSpan.FromSeconds(1),
        switchDistanceMargin: 2.0D);

    AssertEqual((ushort)20, held?.Target.EntityId ?? 0, "stable target should be kept during hold window");

    var smallGain = NextTargetPreAimSelector.Select(
        new[] { currentTarget, slightlyCloser },
        player,
        home,
        30,
        currentTargetEntityId: 99,
        currentTargetServerObjectId: 9999,
        localSideServerObjectId: 0,
        localSidePetServerObjectId: 0,
        allowClaimedByOther: false,
        preferAggressiveMonsters: false,
        currentSelection: currentSelection,
        now: now.AddSeconds(2),
        minimumHold: TimeSpan.FromSeconds(1),
        switchDistanceMargin: 2.0D);

    AssertEqual((ushort)20, smallGain?.Target.EntityId ?? 0, "stable target should be kept when distance gain is small");

    var largeGain = NextTargetPreAimSelector.Select(
        new[] { currentTarget, muchCloser },
        player,
        home,
        30,
        currentTargetEntityId: 99,
        currentTargetServerObjectId: 9999,
        localSideServerObjectId: 0,
        localSidePetServerObjectId: 0,
        allowClaimedByOther: false,
        preferAggressiveMonsters: false,
        currentSelection: currentSelection,
        now: now.AddSeconds(2),
        minimumHold: TimeSpan.FromSeconds(1),
        switchDistanceMargin: 2.0D);

    AssertEqual((ushort)22, largeGain?.Target.EntityId ?? 0, "stable target should switch when a much closer peer appears");

    var threat = new WorldObjectSnapshot(23, 2023, "new-threat", "monster", new Vector3Snapshot(12, 0, 0), 12, 100, 100, TargetServerObjectId: 7000);
    var higherPriority = NextTargetPreAimSelector.Select(
        new[] { currentTarget, threat },
        player,
        home,
        30,
        currentTargetEntityId: 99,
        currentTargetServerObjectId: 9999,
        localSideServerObjectId: 7000,
        localSidePetServerObjectId: 0,
        allowClaimedByOther: false,
        preferAggressiveMonsters: false,
        currentSelection: currentSelection,
        now: now.AddMilliseconds(200),
        minimumHold: TimeSpan.FromSeconds(1),
        switchDistanceMargin: 2.0D);

    AssertEqual((ushort)23, higherPriority?.Target.EntityId ?? 0, "higher-priority local threat should switch immediately");
    return Task.CompletedTask;
}

static async Task TestSmartPreAimStabilizesAlignedTargetSwitchingAsync()
{
    var settings = CreateScriptSettings();
    settings.MainMode = AccountMainMode.CustomCombat;
    settings.CombatMode = AccountCombatMode.Stationary;
    settings.Combat = new CombatScriptSettings
    {
        SmartPreAimEnabled = true,
        PreferAggressiveMonsters = true,
        HasStationaryCombatPosition = true,
        StationaryCombatRadius = 30
    };
    settings.Team.GroupDistanceMeters = 30;

    var alignedTarget = new WorldObjectSnapshot(
        20,
        2020,
        "aligned",
        "monster",
        new Vector3Snapshot(8, 0, 0),
        8,
        100,
        100);
    var ordinaryReplacement = new WorldObjectSnapshot(
        21,
        2021,
        "replacement",
        "monster",
        new Vector3Snapshot(5, 0, 0),
        5,
        100,
        100);
    var urgentThreat = new WorldObjectSnapshot(
        22,
        2022,
        "urgent",
        "monster",
        new Vector3Snapshot(12, 0, 0),
        12,
        100,
        100,
        TargetServerObjectId: 7000);
    var secondUrgentThreat = new WorldObjectSnapshot(
        26,
        2026,
        "second-urgent",
        "monster",
        new Vector3Snapshot(14, 0, 0),
        14,
        100,
        100,
        TargetServerObjectId: 7000);
    var fartherAggressive = new WorldObjectSnapshot(
        23,
        2023,
        "farther-aggressive",
        "monster",
        new Vector3Snapshot(12, 0, 0),
        12,
        100,
        100,
        AggressiveKnown: true,
        IsAggressiveToPlayer: true);
    var slightlyCloserAggressive = new WorldObjectSnapshot(
        24,
        2024,
        "slightly-closer-aggressive",
        "monster",
        new Vector3Snapshot(7, 0, 0),
        7,
        100,
        100,
        AggressiveKnown: true,
        IsAggressiveToPlayer: true);
    var clearlyCloserAggressive = new WorldObjectSnapshot(
        25,
        2025,
        "clearly-closer-aggressive",
        "monster",
        new Vector3Snapshot(6, 0, 0),
        6,
        100,
        100,
        AggressiveKnown: true,
        IsAggressiveToPlayer: true);
    var differentCloserAggressive = clearlyCloserAggressive with
    {
        EntityId = clearlyCloserAggressive.EntityId,
        ServerObjectId = 2030,
        Name = "different-closer-aggressive",
        Position = new Vector3Snapshot(5, 0, 0),
        DistanceToLocalPlayer = 5
    };
    var teamThreat = new WorldObjectSnapshot(
        27,
        2027,
        "team-threat",
        "monster",
        new Vector3Snapshot(14, 0, 0),
        14,
        100,
        100,
        TargetServerObjectId: 8000);
    var secondTeamThreat = teamThreat with
    {
        EntityId = 31,
        ServerObjectId = 2031,
        Name = "second-team-threat",
        Position = new Vector3Snapshot(5, 0, 0),
        DistanceToLocalPlayer = 5
    };
    var selfMember = CreatePartyMemberSnapshot(7000, "self", isSelf: true, isLeader: true, distanceToLocal: 0);
    var protectedMember = CreatePartyMemberSnapshot(8000, "protected", isSelf: false, isLeader: false, distanceToLocal: 5);
    var gameApi = new FakeGameApi
    {
        WorldObjects = new[] { ordinaryReplacement },
        Party = CreateTeamSupportParty(selfMember, protectedMember),
        SummonedPetRoster = SummonedPetRosterSnapshot.Empty(7000, DateTimeOffset.Now)
    };
    var controller = new StationaryCombatController(
        new RecordingKeyboardInput(),
        new SemiAutoCombatController(new RecordingKeyboardInput()));
    var context = CreateContext(settings, gameApi, new InMemoryRoadhogLogger());
    var state = new StationaryCombatState
    {
        LocalCombatSideServerObjectId = 7000,
        Fighting = true,
        CurrentTargetEntityId = 100,
        CurrentTargetServerObjectId = 5000
    };
    var preAim = state.NextTargetPreAim;
    preAim.TargetEntityId = alignedTarget.EntityId;
    preAim.TargetServerObjectId = alignedTarget.ServerObjectId;
    preAim.TargetName = alignedTarget.Name;
    preAim.TargetPosition = alignedTarget.Position;
    preAim.TargetPriorityTier = 1;
    preAim.TargetDistanceToOrigin = 8;
    preAim.TargetSelectedAt = DateTimeOffset.Now - TimeSpan.FromSeconds(2);
    preAim.LastAlignedAt = DateTimeOffset.Now;
    preAim.SessionId = 1;
    preAim.FightTargetEntityId = 100;
    preAim.FightTargetServerObjectId = 5000;

    var refreshMethod = typeof(StationaryCombatController).GetMethod(
        "RefreshNextTargetPreAimSelectionAsync",
        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
    AssertFalse(refreshMethod is null, "smart pre-aim refresh helper should exist");

    async Task RefreshAsync()
    {
        var task = (Task)refreshMethod!.Invoke(
            controller,
            new object[]
            {
                context,
                state,
                new Vector3Snapshot(0, 0, 0),
                new Vector3Snapshot(0, 0, 0),
                30D,
                (ushort)100,
                5000u,
                state.NextTargetPreAim.SessionId
            })!;
        await task.ConfigureAwait(false);
    }

    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(ordinaryReplacement.EntityId, preAim.TargetEntityId, "trusted replacement snapshot should switch immediately");

    gameApi.WorldObjects = new[] { alignedTarget };
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(alignedTarget.EntityId, preAim.TargetEntityId, "trusted aligned snapshot should switch immediately");

    gameApi.WorldObjects = new[] { ordinaryReplacement };
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(ordinaryReplacement.EntityId, preAim.TargetEntityId, "trusted missing-current snapshot should accept replacement immediately");

    void ResetAlignedSelection(
        WorldObjectSnapshot target,
        int priorityTier,
        bool targetingLocalSide,
        bool aggressivePriority,
        bool targetingTeamSide = false)
    {
        preAim.TargetEntityId = target.EntityId;
        preAim.TargetServerObjectId = target.ServerObjectId;
        preAim.TargetName = target.Name;
        preAim.TargetPosition = target.Position;
        preAim.TargetPriorityTier = priorityTier;
        preAim.TargetDistanceToOrigin = target.DistanceToLocalPlayer ?? 0;
        preAim.TargetingLocalSide = targetingLocalSide;
        preAim.TargetingTeamSide = targetingTeamSide;
        preAim.AggressivePriority = aggressivePriority;
        preAim.TargetSelectedAt = DateTimeOffset.Now - TimeSpan.FromSeconds(2);
        preAim.LastAlignedAt = DateTimeOffset.Now;
        preAim.ResetPendingSwitchConfirmation();
        preAim.ClearDisplacedTargetGuard();
    }

    ResetAlignedSelection(alignedTarget, 1, targetingLocalSide: false, aggressivePriority: false);
    gameApi.WorldObjects = new[] { alignedTarget, fartherAggressive };
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(alignedTarget.EntityId, preAim.TargetEntityId, "a farther aggressive target should not replace a visible aligned target");

    gameApi.WorldObjects = new[] { alignedTarget, slightlyCloserAggressive };
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(alignedTarget.EntityId, preAim.TargetEntityId, "an aggressive target only one meter closer should stay inside the two meter stability margin");

    gameApi.WorldObjects = new[] { alignedTarget, clearlyCloserAggressive };
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(alignedTarget.EntityId, preAim.TargetEntityId, "first closer snapshot should keep the aligned target");
    AssertEqual(1, preAim.ConsecutiveBetterTargetSnapshots, "first closer candidate confirmation count");
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(alignedTarget.EntityId, preAim.TargetEntityId, "second closer snapshot should keep the aligned target");
    AssertEqual(2, preAim.ConsecutiveBetterTargetSnapshots, "second closer candidate confirmation count");
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(clearlyCloserAggressive.EntityId, preAim.TargetEntityId, "third closer snapshot should replace the aligned target");
    AssertEqual(0, preAim.ConsecutiveBetterTargetSnapshots, "confirmed closer switch should reset its counter");
    AssertEqual(alignedTarget.ServerObjectId, preAim.DisplacedTargetServerObjectId, "camera-committed switch should remember the displaced target");
    AssertEqual(clearlyCloserAggressive.ServerObjectId, preAim.DisplacedTargetReplacementServerObjectId, "camera-committed switch should bind the displacement to its replacement");
    AssertFalse(preAim.DisplacedTargetGuardActive, "displaced target guard should remain inactive until the replacement is consumed");

    ResetAlignedSelection(alignedTarget, 1, targetingLocalSide: false, aggressivePriority: false);
    gameApi.WorldObjects = new[] { alignedTarget, clearlyCloserAggressive };
    await RefreshAsync().ConfigureAwait(false);
    gameApi.WorldObjects = new[] { alignedTarget, differentCloserAggressive };
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(alignedTarget.EntityId, preAim.TargetEntityId, "a different closer candidate should restart confirmation instead of switching");
    AssertEqual(1, preAim.ConsecutiveBetterTargetSnapshots, "different closer candidate should restart at one confirmation");
    AssertEqual(differentCloserAggressive.ServerObjectId, preAim.PendingSwitchTargetServerObjectId, "pending switch identity should follow server-object identity");

    ResetAlignedSelection(alignedTarget, 1, targetingLocalSide: false, aggressivePriority: false);
    gameApi.WorldObjects = new[] { alignedTarget, urgentThreat };
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(urgentThreat.EntityId, preAim.TargetEntityId, "a farther target attacking the local side should replace an aligned target immediately");

    var teamTargetedThreat = urgentThreat with { TargetServerObjectId = 9000 };
    ResetAlignedSelection(urgentThreat, 4, targetingLocalSide: true, aggressivePriority: false);
    gameApi.WorldObjects = new[] { teamTargetedThreat, ordinaryReplacement };
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(ordinaryReplacement.EntityId, preAim.TargetEntityId, "trusted local-threat downgrade should accept the replacement immediately");

    ResetAlignedSelection(urgentThreat, 4, targetingLocalSide: true, aggressivePriority: false);
    gameApi.WorldObjects = new[] { urgentThreat, ordinaryReplacement };
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(urgentThreat.EntityId, preAim.TargetEntityId, "reconfirmed local threat should stay selected");

    gameApi.WorldObjects = new[] { teamTargetedThreat, ordinaryReplacement };
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(ordinaryReplacement.EntityId, preAim.TargetEntityId, "trusted local-threat downgrade should switch without a read counter");

    var targetFieldClearedThreat = urgentThreat with { TargetServerObjectId = 0 };
    ResetAlignedSelection(urgentThreat, 4, targetingLocalSide: true, aggressivePriority: false);
    gameApi.WorldObjects = new[] { targetFieldClearedThreat };
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(urgentThreat.EntityId, preAim.TargetEntityId, "trusted cleared target field should keep the same target identity");
    AssertEqual(1, preAim.TargetPriorityTier, "trusted cleared target field should downgrade immediately");

    ResetAlignedSelection(urgentThreat, 4, targetingLocalSide: true, aggressivePriority: false);
    gameApi.WorldObjects = new[] { teamTargetedThreat, secondUrgentThreat };
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(secondUrgentThreat.EntityId, preAim.TargetEntityId, "a newly confirmed local threat should replace an unconfirmed aligned threat immediately");

    var claimedAlignedTarget = alignedTarget with { TargetServerObjectId = 9000 };
    ResetAlignedSelection(alignedTarget, 1, targetingLocalSide: false, aggressivePriority: false);
    preAim.LastAlignedAt = DateTimeOffset.MinValue;
    preAim.LastAdjustedAt = DateTimeOffset.Now;
    gameApi.WorldObjects = new[] { claimedAlignedTarget, ordinaryReplacement };
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(ordinaryReplacement.EntityId, preAim.TargetEntityId, "trusted ordinary invalid snapshot should switch immediately");

    var playerNearTarget = alignedTarget with
    {
        EntityId = 28,
        ServerObjectId = 2028,
        Name = "player-near",
        Position = new Vector3Snapshot(2, 0, 0),
        DistanceToLocalPlayer = 2
    };
    var fightNearButPlayerFarTarget = ordinaryReplacement with
    {
        EntityId = 29,
        ServerObjectId = 2029,
        Name = "fight-near-player-far",
        Position = new Vector3Snapshot(9, 0, 0),
        DistanceToLocalPlayer = 9
    };
    settings.Combat.SmartPreAimUseFightTargetPosition = true;
    ResetAlignedSelection(playerNearTarget, 1, targetingLocalSide: false, aggressivePriority: false);
    preAim.FightTargetPosition = new Vector3Snapshot(10, 0, 0);
    gameApi.WorldObjects = new[] { playerNearTarget, fightNearButPlayerFarTarget };
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(playerNearTarget.EntityId, preAim.TargetEntityId, "a target farther from the player must not replace the aligned target when the moving fight origin prefers it");
    AssertEqual(0, preAim.ConsecutiveBetterTargetSnapshots, "farther player-distance candidate should not start switch confirmation");
    settings.Combat.SmartPreAimUseFightTargetPosition = false;

    ResetAlignedSelection(alignedTarget, 1, targetingLocalSide: false, aggressivePriority: false);
    gameApi.WorldObjects = new[] { alignedTarget, teamThreat };
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(teamThreat.EntityId, preAim.TargetEntityId, "a confirmed team-side threat should replace an aligned ordinary target immediately");
    AssertEqual(3, preAim.TargetPriorityTier, "team-side threat should use the protected-team tier");
    AssertFalse(!preAim.TargetingTeamSide, "stored smart pre-aim state should preserve team-side threat classification");

    ResetAlignedSelection(
        teamThreat,
        3,
        targetingLocalSide: false,
        aggressivePriority: false,
        targetingTeamSide: true);
    gameApi.WorldObjects = new[] { teamThreat, secondTeamThreat };
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(teamThreat.EntityId, preAim.TargetEntityId, "an equal-priority team threat should not cause an immediate camera reversal");
    AssertEqual(1, preAim.ConsecutiveBetterTargetSnapshots, "equal-priority team threat should start normal closer-target confirmation");
    await RefreshAsync().ConfigureAwait(false);
    await RefreshAsync().ConfigureAwait(false);
    AssertEqual(secondTeamThreat.EntityId, preAim.TargetEntityId, "an equal-priority team threat should switch after three stable closer snapshots");

    preAim.PendingSwitchTargetEntityId = 99;
    preAim.PendingSwitchTargetServerObjectId = 9099;
    preAim.ConsecutiveBetterTargetSnapshots = 2;
    preAim.ClearCandidate();
    AssertEqual(0, preAim.ConsecutiveBetterTargetSnapshots, "clearing pre-aim state should reset pending switch confirmations");
    AssertEqual(0u, preAim.PendingSwitchTargetServerObjectId, "clearing pre-aim state should reset pending switch identity");
}

static async Task TestSmartPreAimHandoffKeepsCommittedTargetAsync()
{
    var settings = CreateScriptSettings();
    settings.MainMode = AccountMainMode.CustomCombat;
    settings.CombatMode = AccountCombatMode.Stationary;
    settings.Combat = new CombatScriptSettings
    {
        SmartPreAimEnabled = true,
        PreferAggressiveMonsters = true,
        HasStationaryCombatPosition = true,
        StationaryCombatRadius = 30
    };
    var committed = new WorldObjectSnapshot(
        41,
        4041,
        "committed-b",
        "monster",
        new Vector3Snapshot(20, 0, 0),
        20,
        100,
        100);
    var closerAggressive = new WorldObjectSnapshot(
        42,
        4042,
        "closer-c",
        "monster",
        new Vector3Snapshot(5, 0, 0),
        5,
        100,
        100,
        AggressiveKnown: true,
        IsAggressiveToPlayer: true);
    var gameApi = new FakeGameApi
    {
        WorldObjects = new[] { closerAggressive, committed }
    };
    var controller = new StationaryCombatController(
        new RecordingKeyboardInput(),
        new SemiAutoCombatController(new RecordingKeyboardInput()));
    var state = new StationaryCombatState();
    SeedAlignedSmartPreAimCandidate(state, committed);

    var selected = await SelectStationaryTargetForTestAsync(
            controller,
            CreateContext(settings, gameApi, new InMemoryRoadhogLogger()),
            state,
            allowClaimedByOther: false)
        .ConfigureAwait(false);

    AssertEqual(committed.ServerObjectId, selected?.ServerObjectId ?? 0, "aligned B should become the committed handoff target even when aggressive C is closer");
    AssertFalse(!state.IsSmartPreAimHandoffTarget(committed.EntityId, committed.ServerObjectId), "aligned B should start the handoff before movement or Tab");

    state.MarkCandidate(committed, DateTimeOffset.Now);
    selected = await SelectStationaryTargetForTestAsync(
            controller,
            CreateContext(settings, gameApi, new InMemoryRoadhogLogger()),
            state,
            allowClaimedByOther: false)
        .ConfigureAwait(false);
    AssertEqual(committed.ServerObjectId, selected?.ServerObjectId ?? 0, "ordinary closer aggressive C must not replace B during the handoff");
}

static async Task TestSmartPreAimHandoffConfirmsMissingTargetAsync()
{
    var settings = CreateScriptSettings();
    settings.MainMode = AccountMainMode.CustomCombat;
    settings.CombatMode = AccountCombatMode.Stationary;
    settings.Combat = new CombatScriptSettings
    {
        SmartPreAimEnabled = true,
        HasStationaryCombatPosition = true,
        StationaryCombatRadius = 30
    };
    var committed = new WorldObjectSnapshot(
        41,
        4041,
        "missing-b",
        "monster",
        new Vector3Snapshot(20, 0, 0),
        20,
        100,
        100);
    var fallback = new WorldObjectSnapshot(
        42,
        4042,
        "fallback-c",
        "monster",
        new Vector3Snapshot(5, 0, 0),
        5,
        100,
        100);
    var gameApi = new FakeGameApi
    {
        WorldObjects = new[] { fallback }
    };
