    AssertFalse(!contestState.HasSmartPreAimHandoff, "contest mode should keep the claimed B handoff active");
}

static async Task TestSmartPreAimHandoffYieldsToLocalDefenseAsync()
{
    var settings = CreateScriptSettings();
    settings.MainMode = AccountMainMode.CustomCombat;
    settings.CombatMode = AccountCombatMode.Stationary;
    settings.Combat = new CombatScriptSettings
    {
        SmartPreAimEnabled = true,
        HasStationaryCombatPosition = true,
        StationaryCombatX = 0,
        StationaryCombatY = 0,
        StationaryCombatZ = 0,
        StationaryCombatRadius = 30
    };
    var committed = new WorldObjectSnapshot(
        41,
        4041,
        "committed-b",
        "monster",
        new Vector3Snapshot(20, 0, 0),
        20,
        100,
        100);
    var defense = new WorldObjectSnapshot(
        42,
        4042,
        "defense-c",
        "monster",
        new Vector3Snapshot(8, 0, 0),
        8,
        100,
        100,
        TargetServerObjectId: 7000,
        AggressiveKnown: true,
        IsAggressiveToPlayer: true);
    var gameApi = new FakeGameApi
    {
        Player = new PlayerSnapshot(1, 0, "Fake", 100, 100, 100, 100, 0, new Vector3Snapshot(0, 0, 0), DateTimeOffset.Now, 90, 10, 90),
        WorldObjects = new[] { committed, defense },
        Skills = CreateSkillSnapshotsById(new Dictionary<uint, uint>
        {
            [1] = 0,
            [5] = 0,
            [6] = 0,
            [7] = 0,
            [8] = 0,
            [9] = 0,
            [10] = 0
        })
    };
    var keyboard = new RecordingKeyboardInput();
    var controller = new StationaryCombatController(keyboard, new SemiAutoCombatController(keyboard));
    var state = new StationaryCombatState
    {
        LocalCombatSideServerObjectId = 7000
    };
    SeedAlignedSmartPreAimCandidate(state, committed);
    state.StartSmartPreAimHandoff(committed.EntityId, committed.ServerObjectId);
    state.MarkCandidate(committed, DateTimeOffset.Now);

    await controller
        .TickAsync(
            CreateContext(settings, gameApi, new InMemoryRoadhogLogger()),
            SemiAutoSkillPlan.FromSettings(settings.Skills),
            new SemiAutoCombatState(),
            state)
        .ConfigureAwait(false);

    AssertEqual(defense.ServerObjectId, state.CandidateServerObjectId, "a monster attacking the local side must override committed B");
    AssertFalse(state.HasSmartPreAimHandoff, "local defense override should release the B handoff");
    AssertFalse(state.NextTargetPreAim.HasCandidate, "local defense override should clear the stale B pre-aim result");
}

static async Task TestSmartPreAimHandoffCompletesBeforeNextPreAimAsync()
{
    var settings = CreateScriptSettings();
    settings.MainMode = AccountMainMode.CustomCombat;
    settings.CombatMode = AccountCombatMode.Stationary;
    settings.Combat = new CombatScriptSettings
    {
        SmartPreAimEnabled = true,
        HasStationaryCombatPosition = true,
        StationaryCombatX = 0,
        StationaryCombatY = 0,
        StationaryCombatZ = 0,
        StationaryCombatRadius = 30
    };
    var committed = new WorldObjectSnapshot(
        41,
        4041,
        "committed-b",
        "monster",
        new Vector3Snapshot(8, 0, 0),
        8,
        1000,
        1000,
        TargetServerObjectId: 7000,
        IsTargetingLocalPlayer: true);
    var next = new WorldObjectSnapshot(
        42,
        4042,
        "next-c",
        "monster",
        new Vector3Snapshot(12, 0, 0),
        12,
        1000,
        1000);
    var gameApi = new FakeGameApi
    {
        Player = new PlayerSnapshot(1, 0, "Fake", 100, 100, 100, 100, 0, new Vector3Snapshot(0, 0, 0), DateTimeOffset.Now, 90, 10, 90),
        TargetEntityId = committed.EntityId,
        TargetOwnServerObjectId = committed.ServerObjectId,
        TargetCurrentHp = committed.CurrentHp,
        TargetMaxHp = committed.MaxHp,
        TargetName = committed.Name,
        TargetPosition = committed.Position,
        TargetServerObjectId = 7000,
        TargetIsTargetingLocalPlayer = true,
        LocalServerObjectId = 7000,
        WorldObjects = new[] { committed, next },
        Skills = CreateSkillSnapshotsById(new Dictionary<uint, uint>
        {
            [1] = 0,
            [5] = 0,
            [6] = 0,
            [7] = 0,
            [8] = 0,
            [9] = 0,
            [10] = 0
        })
    };
    var keyboard = new RecordingKeyboardInput();
    var logger = new InMemoryRoadhogLogger();
    var controller = new StationaryCombatController(keyboard, new SemiAutoCombatController(keyboard));
    var context = CreateContext(settings, gameApi, logger);
    var state = new StationaryCombatState
    {
        LocalCombatSideServerObjectId = 7000,
        Fighting = true,
        CurrentTargetEntityId = 39,
        CurrentTargetServerObjectId = 4039
    };
    state.NextTargetPreAim.RecordDisplacedTargetGuard(40, 4040, committed.EntityId, committed.ServerObjectId);
    state.ClearTarget();
    AssertEqual(committed.ServerObjectId, state.NextTargetPreAim.DisplacedTargetReplacementServerObjectId, "ending A fight should preserve its pending A-to-B displacement record");
    SeedAlignedSmartPreAimCandidate(state, committed);
    AssertFalse(!state.NextTargetPreAim.ActivateDisplacedTargetGuard(committed.EntityId, committed.ServerObjectId), "handoff test should preserve the narrow A guard for B fight");
    state.StartSmartPreAimHandoff(committed.EntityId, committed.ServerObjectId);
    state.MarkCandidate(committed, DateTimeOffset.Now);
    var plan = SemiAutoSkillPlan.FromSettings(settings.Skills);
    var semiAutoState = new SemiAutoCombatState();

    await controller.TickAsync(context, plan, semiAutoState, state).ConfigureAwait(false);

    AssertFalse(!state.Fighting, "locked B should become the formal fight target");
    AssertEqual(committed.ServerObjectId, state.CurrentTargetServerObjectId, "formal fight should retain committed B identity");
    AssertFalse(state.HasSmartPreAimHandoff, "formal B fight should clear the handoff before the next pre-aim starts");
    AssertFalse(!state.NextTargetPreAim.DisplacedTargetGuardActive, "formal B fight should retain only the narrow A bounce guard");

    await controller.TickAsync(context, plan, semiAutoState, state).ConfigureAwait(false);

    AssertFalse(!logger.Entries.Any(entry =>
        entry.EventName == "stationary_combat.smart_preaim.started" &&
        Equals(Convert.ToUInt32(entry.Fields["fightTargetServerObjectId"]), committed.ServerObjectId)),
        "the next pre-aim should restart after B is formally fighting");
    AssertFalse(state.HasSmartPreAimHandoff, "restarted pre-aim must not recreate the completed handoff during B fight");
    state.ClearTarget();
    AssertFalse(state.NextTargetPreAim.DisplacedTargetGuardActive, "ending B fight should clear its narrow displaced-A guard");
}

static void SeedAlignedSmartPreAimCandidate(StationaryCombatState state, WorldObjectSnapshot target)
{
    var preAim = state.NextTargetPreAim;
    preAim.TargetEntityId = target.EntityId;
    preAim.TargetServerObjectId = target.ServerObjectId;
    preAim.TargetName = target.Name;
    preAim.TargetPosition = target.Position;
    preAim.TargetSelectedAt = DateTimeOffset.Now;
    preAim.LastAlignedAt = DateTimeOffset.Now;
}

static async Task<WorldObjectSnapshot?> SelectStationaryTargetForTestAsync(
    StationaryCombatController controller,
    AccountWorkerContext context,
    StationaryCombatState state,
    bool allowClaimedByOther)
{
    var method = typeof(StationaryCombatController).GetMethod(
        "SelectTargetAsync",
        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
    AssertFalse(method is null, "stationary target selection helper should exist");
    var task = (Task<WorldObjectSnapshot?>)method!.Invoke(
        controller,
        new object[]
        {
            context,
            state,
            new Vector3Snapshot(0, 0, 0),
            new Vector3Snapshot(0, 0, 0),
            30D,
            allowClaimedByOther
        })!;
    return await task.ConfigureAwait(false);
}

static async Task TestSmartPreAimPreventsConsumedTargetBounceAsync()
{
    var settings = CreateScriptSettings();
    settings.MainMode = AccountMainMode.CustomCombat;
    settings.CombatMode = AccountCombatMode.Stationary;
    settings.Combat = new CombatScriptSettings
    {
        SmartPreAimEnabled = true,
        HasStationaryCombatPosition = true,
        StationaryCombatRadius = 30
    };

    var displaced = new WorldObjectSnapshot(
        40,
        4040,
        "displaced-a",
        "monster",
        new Vector3Snapshot(4, 0, 0),
        4,
        100,
        100);
    var consumedReplacement = new WorldObjectSnapshot(
        41,
        4041,
        "consumed-b",
        "monster",
        new Vector3Snapshot(6, 0, 0),
        6,
        100,
        100);
    var fallback = new WorldObjectSnapshot(
        42,
        4042,
        "fallback-c",
        "monster",
        new Vector3Snapshot(10, 0, 0),
        10,
        100,
        100);
    var gameApi = new FakeGameApi
    {
        WorldObjects = new[] { displaced, consumedReplacement, fallback }
    };
    var controller = new StationaryCombatController(
        new RecordingKeyboardInput(),
        new SemiAutoCombatController(new RecordingKeyboardInput()));
    var context = CreateContext(settings, gameApi, new InMemoryRoadhogLogger());
    var state = new StationaryCombatState
    {
        Fighting = true,
        CurrentTargetEntityId = consumedReplacement.EntityId,
        CurrentTargetServerObjectId = consumedReplacement.ServerObjectId,
        LocalCombatSideServerObjectId = 7000
    };
    var preAim = state.NextTargetPreAim;
    preAim.SessionId = 1;
    preAim.FightTargetEntityId = consumedReplacement.EntityId;
    preAim.FightTargetServerObjectId = consumedReplacement.ServerObjectId;
    preAim.RecordDisplacedTargetGuard(
        displaced.EntityId,
        displaced.ServerObjectId,
        consumedReplacement.EntityId,
        consumedReplacement.ServerObjectId);
    AssertFalse(!preAim.ActivateDisplacedTargetGuard(
        consumedReplacement.EntityId,
        consumedReplacement.ServerObjectId), "consuming the replacement should activate its displaced-target guard");
    preAim.ClearCandidate();
    AssertFalse(!preAim.DisplacedTargetGuardActive, "candidate clearing after consume must preserve the active cross-fight guard");

    var refreshMethod = typeof(StationaryCombatController).GetMethod(
        "RefreshNextTargetPreAimSelectionAsync",
        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
    AssertFalse(refreshMethod is null, "smart pre-aim refresh helper should exist");

    async Task RefreshAsync(ushort fightTargetEntityId, uint fightTargetServerObjectId)
    {
        if (!StationaryCombatState.IsSameTarget(
                preAim.FightTargetEntityId,
                preAim.FightTargetServerObjectId,
                fightTargetEntityId,
                fightTargetServerObjectId))
        {
            preAim.SessionId++;
            preAim.FightTargetEntityId = fightTargetEntityId;
            preAim.FightTargetServerObjectId = fightTargetServerObjectId;
        }

        var task = (Task)refreshMethod!.Invoke(
            controller,
            new object[]
            {
                context,
                state,
                new Vector3Snapshot(0, 0, 0),
                new Vector3Snapshot(0, 0, 0),
                30D,
                fightTargetEntityId,
                fightTargetServerObjectId,
                state.NextTargetPreAim.SessionId
            })!;
        await task.ConfigureAwait(false);
    }

    await RefreshAsync(consumedReplacement.EntityId, consumedReplacement.ServerObjectId).ConfigureAwait(false);
    AssertEqual(fallback.EntityId, preAim.TargetEntityId, "the fight that consumed B must not immediately pre-aim displaced A again");

    preAim.ClearCandidate();
    var reusedEntity = displaced with
    {
        ServerObjectId = 9090,
        Name = "reused-entity-id"
    };
    gameApi.WorldObjects = new[] { reusedEntity, consumedReplacement, fallback };
    await RefreshAsync(consumedReplacement.EntityId, consumedReplacement.ServerObjectId).ConfigureAwait(false);
    AssertEqual(reusedEntity.ServerObjectId, preAim.TargetServerObjectId, "server-object identity should prevent the guard from excluding a new monster that reused A's entity id");

    preAim.ClearCandidate();
    var localThreat = displaced with
    {
        IsTargetingLocalPlayer = true,
        TargetServerObjectId = 7000
    };
    gameApi.WorldObjects = new[] { localThreat, consumedReplacement, fallback };
    await RefreshAsync(consumedReplacement.EntityId, consumedReplacement.ServerObjectId).ConfigureAwait(false);
    AssertEqual(displaced.EntityId, preAim.TargetEntityId, "a displaced target attacking the local side must bypass the cross-fight guard");
    AssertEqual(4, preAim.TargetPriorityTier, "local-side threat should retain the hard smart pre-aim priority");

    preAim.ClearCandidate();
    state.CurrentTargetEntityId = fallback.EntityId;
    state.CurrentTargetServerObjectId = fallback.ServerObjectId;
    gameApi.WorldObjects = new[] { displaced, consumedReplacement };
    await RefreshAsync(fallback.EntityId, fallback.ServerObjectId).ConfigureAwait(false);
    AssertEqual(displaced.EntityId, preAim.TargetEntityId, "changing the foreground fight target should release the displaced-target guard");
    AssertFalse(preAim.DisplacedTargetGuardActive, "cross-fight guard should clear after its replacement fight ends");

}

static Task TestSmartPreAimSelectorAppliesNormalFiltersAsync()
{
    var player = new Vector3Snapshot(0, 0, 0);
    var home = new Vector3Snapshot(0, 0, 0);
    var now = new DateTimeOffset(2026, 8, 7, 12, 0, 0, TimeSpan.Zero);
    var ignored = new WorldObjectSnapshot(30, 3030, "ignored", "monster", new Vector3Snapshot(2, 0, 0), 2, 100, 100);
    var temporary = new WorldObjectSnapshot(31, 3031, "temporary", "monster", new Vector3Snapshot(3, 0, 0), 3, 100, 100);
    var filtered = new WorldObjectSnapshot(32, 3032, "filtered", "monster", new Vector3Snapshot(4, 0, 0), 4, 100, 100);
    var claimed = new WorldObjectSnapshot(33, 3033, "claimed", "monster", new Vector3Snapshot(5, 0, 0), 5, 100, 100, TargetServerObjectId: 9999);
    var ordinary = new WorldObjectSnapshot(34, 3034, "ordinary", "monster", new Vector3Snapshot(8, 0, 0), 8, 100, 100);
    var exclusions = new NextTargetPreAimExclusionSnapshot(
        new[] { ignored.EntityId },
        Array.Empty<uint>(),
        Array.Empty<ushort>(),
        new[] { temporary.ServerObjectId });
    var currentSelection = new NextTargetPreAimSelection(
        ignored,
        1,
        2,
        IsTargetingLocalSide: false,
        IsTargetingTeamSide: false,
        IsAggressivePriority: false,
        now,
        "current");

    var selected = NextTargetPreAimSelector.Select(
        new[] { ignored, temporary, filtered, claimed, ordinary },
        player,
        home,
        30,
        currentTargetEntityId: 99,
        currentTargetServerObjectId: 9999,
        localSideServerObjectId: 1000,
        localSidePetServerObjectId: 0,
        allowClaimedByOther: false,
        preferAggressiveMonsters: false,
        activeMonsterNameFilters: new[] { "filtered" },
        currentSelection: currentSelection,
        now: now.AddMilliseconds(100),
        minimumHold: TimeSpan.FromSeconds(1),
        switchDistanceMargin: 20.0D,
        exclusions: exclusions);

    AssertEqual((ushort)34, selected?.Target.EntityId ?? 0, "smart pre-aim ordinary target should follow normal filters before stability");
    AssertEqual("current_invalid", selected?.DecisionReason ?? string.Empty, "filtered current pre-aim target should not be kept by stability");

    var localIgnored = ignored with
    {
        EntityId = 35,
        ServerObjectId = 3035,
        Name = "ignored-local",
        IsTargetingLocalPlayer = true,
        Position = new Vector3Snapshot(12, 0, 0),
        DistanceToLocalPlayer = 12
    };
    var localSelected = NextTargetPreAimSelector.Select(
        new[] { localIgnored, ordinary },
        player,
        home,
        30,
        currentTargetEntityId: 99,
        currentTargetServerObjectId: 9999,
        localSideServerObjectId: 1000,
        localSidePetServerObjectId: 0,
        allowClaimedByOther: false,
        preferAggressiveMonsters: false,
        activeMonsterNameFilters: Array.Empty<string>(),
        exclusions: new NextTargetPreAimExclusionSnapshot(
            new[] { localIgnored.EntityId },
            new[] { localIgnored.ServerObjectId },
            Array.Empty<ushort>(),
            Array.Empty<uint>()));

    AssertEqual((ushort)35, localSelected?.Target.EntityId ?? 0, "ignored local-side threat should still follow normal defense target behavior");
    AssertEqual(4, localSelected?.PriorityTier ?? 0, "local-side defense threat should keep highest smart pre-aim tier");

    var teamIgnored = localIgnored with
    {
        EntityId = 37,
        ServerObjectId = 3037,
        Name = "ignored-team",
        IsTargetingLocalPlayer = false,
        TargetServerObjectId = 8000
    };
    var teamSelected = NextTargetPreAimSelector.Select(
        new[] { teamIgnored, ordinary },
        player,
        home,
        30,
        currentTargetEntityId: 99,
        currentTargetServerObjectId: 9999,
        localSideServerObjectId: 1000,
        localSidePetServerObjectId: 0,
        allowClaimedByOther: false,
        preferAggressiveMonsters: false,
        activeMonsterNameFilters: Array.Empty<string>(),
        exclusions: NextTargetPreAimExclusionSnapshot.Empty.WithIgnoredTarget(
            teamIgnored.EntityId,
            teamIgnored.ServerObjectId),
        teamSideServerObjectIds: new HashSet<uint> { 8000 });

    AssertEqual((ushort)37, teamSelected?.Target.EntityId ?? 0, "ignored team-side threat should bypass the displaced-target guard");
    AssertEqual(3, teamSelected?.PriorityTier ?? 0, "team-side threat should retain its protected smart pre-aim tier");

    var localTemporary = localIgnored with
    {
        EntityId = 36,
        ServerObjectId = 3036,
        Name = "temporary-local"
    };
    var localTemporarySkipped = NextTargetPreAimSelector.Select(
        new[] { localTemporary, ordinary },
        player,
        home,
        30,
        currentTargetEntityId: 99,
        currentTargetServerObjectId: 9999,
        localSideServerObjectId: 1000,
        localSidePetServerObjectId: 0,
        allowClaimedByOther: false,
        preferAggressiveMonsters: false,
        activeMonsterNameFilters: Array.Empty<string>(),
        exclusions: new NextTargetPreAimExclusionSnapshot(
            Array.Empty<ushort>(),
            Array.Empty<uint>(),
            Array.Empty<ushort>(),
            new[] { localTemporary.ServerObjectId }));

    AssertEqual((ushort)34, localTemporarySkipped?.Target.EntityId ?? 0, "temporary excluded local-side threat should be skipped like normal defense target selection");
    return Task.CompletedTask;
}

static Task TestSmartPreAimLifecycleSpansLootUntilFinishAsync()
{
    var settings = CreateScriptSettings();
    settings.MainMode = AccountMainMode.CustomCombat;
    settings.CombatMode = AccountCombatMode.Stationary;
    settings.Combat = new CombatScriptSettings
    {
        SmartPreAimEnabled = true,
        HasStationaryCombatPosition = true,
        StationaryCombatX = 0,
        StationaryCombatY = 0,
        StationaryCombatZ = 0,
        StationaryCombatRadius = 30
    };

    var logger = new InMemoryRoadhogLogger();
    var context = CreateContext(settings, new FakeGameApi(), logger);
    var validMethod = typeof(StationaryCombatController).GetMethod(
        "IsSmartPreAimLoopStillValid",
        System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);
    var finishMethod = typeof(StationaryCombatController).GetMethod(
        "FinishLootAfterKill",
        System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);
    AssertFalse(validMethod is null, "smart pre-aim validity helper should exist");
    AssertFalse(finishMethod is null, "loot finish helper should exist");

    bool IsValid(StationaryCombatState targetState)
    {
        return (bool)validMethod!.Invoke(
            null,
            new object[]
            {
                context,
                targetState,
                (ushort)100,
                5000u,
                targetState.NextTargetPreAim.SessionId
            })!;
    }

    var state = new StationaryCombatState
    {
        Fighting = true,
        CurrentTargetEntityId = 100,
        CurrentTargetServerObjectId = 5000
    };
    state.NextTargetPreAim.SessionId = 1;
    state.NextTargetPreAim.FightTargetEntityId = 100;
    state.NextTargetPreAim.FightTargetServerObjectId = 5000;
    AssertFalse(!IsValid(state), "smart pre-aim should be valid while fighting the tracked target");

    var killedTarget = new LockedTargetSnapshot(
        100,
        5000,
        0,
        LockedTargetSnapshot.MonsterObjectType,
        "dead",
        0,
        100,
        new Vector3Snapshot(2, 0, 0),
        2,
        DateTimeOffset.Now,
        LootableRaw: 1,
        InteractionState: 37);
    state.StartLootAfterKill(killedTarget, DateTimeOffset.Now);

    AssertFalse(state.Fighting, "loot start should clear fighting state");
    AssertFalse(!state.LootAfterKill.Active, "loot should be active after killed target enters loot flow");
    AssertFalse(!IsValid(state), "smart pre-aim should remain valid during active loot for the killed target");

    var worker = new TaskCompletionSource();
    state.NextTargetPreAim.Cancellation = new CancellationTokenSource();
    state.NextTargetPreAim.Worker = worker.Task;
    state.NextTargetPreAim.FightTargetEntityId = 100;
    state.NextTargetPreAim.FightTargetServerObjectId = 5000;
    state.NextTargetPreAim.TargetEntityId = 200;
    state.NextTargetPreAim.TargetServerObjectId = 6000;
    state.NextTargetPreAim.TargetName = "next";
    state.NextTargetPreAim.TargetPosition = new Vector3Snapshot(6, 0, 0);
    state.NextTargetPreAim.FightTargetPosition = new Vector3Snapshot(2, 0, 0);
    state.NextTargetPreAim.LastAlignedAt = DateTimeOffset.Now;

    try
    {
        finishMethod!.Invoke(null, new object[] { context, state, "complete", true });

        AssertFalse(state.LootAfterKill.Active, "loot should be inactive after finish");
        AssertFalse(IsValid(state), "smart pre-aim should be invalid after loot finishes");
        AssertFalse(!state.NextTargetPreAim.StopRequested, "smart pre-aim worker should be stopped after loot finishes");
        AssertEqual("loot_after_kill_finished", state.NextTargetPreAim.LastStopReason, "smart pre-aim stop reason after loot finish");
        AssertFalse(!state.NextTargetPreAim.HasCandidate, "stopped smart pre-aim should keep candidate for the next normal selection consume");
        AssertEqual(2D, state.NextTargetPreAim.FightTargetPosition?.X ?? double.NaN, "loot finish should preserve the fight-target distance origin for normal selection");

        var stopped = logger.Entries.LastOrDefault(entry => entry.EventName == "stationary_combat.smart_preaim.stopped");
        AssertFalse(stopped is null, "smart pre-aim stop should be logged after loot finish");
        AssertEqual("loot_after_kill_finished", Convert.ToString(stopped!.Fields["reason"]) ?? string.Empty, "logged smart pre-aim stop reason");
        AssertFalse(Convert.ToBoolean(stopped.Fields["clearCandidate"]), "loot-finish stop should not clear the pre-aim candidate");
    }
    finally
    {
        worker.TrySetResult();
        state.NextTargetPreAim.Cancellation?.Dispose();
        state.NextTargetPreAim.Cancellation = null;
        state.NextTargetPreAim.Worker = null;
    }

    return Task.CompletedTask;
}

static async Task TestSmartPreAimPausesDuringCleanupMouseWorkAsync()
{
    var settings = CreateScriptSettings();
    settings.MainMode = AccountMainMode.CustomCombat;
