static async Task TestStationaryCombatWakesFullNoTargetRestAsync()
{
    var settings = CreateScriptSettings();
    settings.MainMode = AccountMainMode.CustomCombat;
    settings.CombatMode = AccountCombatMode.Stationary;
    settings.Combat = new CombatScriptSettings
    {
        HasStationaryCombatPosition = true,
        StationaryCombatX = 0,
        StationaryCombatY = 0,
        StationaryCombatZ = 0,
        StationaryCombatRadius = 30,
        ReturnHomeWhenNoTarget = true,
        SitWhenNoTargetAtHome = true
    };

    var keyboard = new RecordingKeyboardInput();
    var logger = new InMemoryRoadhogLogger();
    var gameApi = new FakeGameApi
    {
        Player = new PlayerSnapshot(1, 0, "Fake", 99, 100, 100, 100, 0, new Vector3Snapshot(0, 0, 0), DateTimeOffset.Now, 270, 10, 270),
        TargetEntityId = 0,
        TargetCurrentHp = 0,
        TargetMaxHp = 0,
        TargetPosition = null,
        WorldObjects = Array.Empty<WorldObjectSnapshot>(),
        Skills = CreateSkillSnapshotsById(new Dictionary<uint, uint>())
    };
    var controller = new StationaryCombatController(keyboard, new SemiAutoCombatController(keyboard));
    var plan = SemiAutoSkillPlan.FromSettings(settings.Skills);
    var state = new StationaryCombatState();
    var semiAutoState = new SemiAutoCombatState();
    var context = CreateContext(settings, gameApi, logger);

    await controller.TickAsync(context, plan, semiAutoState, state).ConfigureAwait(false);

    AssertSequence(new[] { "OemComma" }, keyboard.Keys.ToArray(), "one non-full resource should enter no-target rest");
    AssertFalse(!state.NoTargetRestActive, "no-target rest should become active before resources are full");
    keyboard.Keys.Clear();

    gameApi.Player = gameApi.Player with
    {
        CurrentHp = 100,
        CurrentMp = 100,
        StanceFlags = 5,
        MotionMode = 1
    };
    await controller.TickAsync(context, plan, semiAutoState, state).ConfigureAwait(false);

    AssertSequence(new[] { "X" }, keyboard.Keys.ToArray(), "full hp and mp should wake no-target rest with x only");
    AssertFalse(!state.NoTargetRestActive, "full-resource wake should wait for stand confirmation");
    AssertFalse(!state.NoTargetRestExitPending, "full-resource wake should track pending stand confirmation");
    keyboard.Keys.Clear();

    gameApi.Player = gameApi.Player with { StanceFlags = 1, MotionMode = 0 };
    await controller.TickAsync(context, plan, semiAutoState, state).ConfigureAwait(false);
    await controller.TickAsync(context, plan, semiAutoState, state).ConfigureAwait(false);

    AssertFalse(state.NoTargetRestActive, "confirmed full-resource stand should clear no-target rest");
    AssertFalse(keyboard.Keys.Contains("OemComma"), "full resources should not immediately re-enter no-target rest");
    AssertFalse(!logger.Entries.Any(entry =>
        entry.EventName == "stationary_combat.no_target.rest_exit" &&
        string.Equals(Convert.ToString(entry.Fields["reason"]), "resources_full", StringComparison.Ordinal)),
        "full-resource wake should log the rest exit reason");
    AssertFalse(!logger.Entries.Any(entry =>
        entry.EventName == "stationary_combat.no_target.rest_exit_confirmed" &&
        string.Equals(Convert.ToString(entry.Fields["reason"]), "resources_full", StringComparison.Ordinal)),
        "full-resource stand confirmation should be logged");
}

static async Task TestStationaryCombatWakesNoTargetRestWhenTargetAppearsAsync()
{
    var settings = CreateScriptSettings();
    settings.MainMode = AccountMainMode.CustomCombat;
    settings.CombatMode = AccountCombatMode.Stationary;
    settings.Combat = new CombatScriptSettings
    {
        HasStationaryCombatPosition = true,
        StationaryCombatX = 0,
        StationaryCombatY = 0,
        StationaryCombatZ = 0,
        StationaryCombatRadius = 30,
        ReturnHomeWhenNoTarget = true,
        SitWhenNoTargetAtHome = true
    };

    var keyboard = new RecordingKeyboardInput();
    var logger = new InMemoryRoadhogLogger();
    var gameApi = new FakeGameApi
    {
        Player = new PlayerSnapshot(1, 0, "Fake", 99, 100, 100, 100, 0, new Vector3Snapshot(0, 0, 0), DateTimeOffset.Now, 270, 10, 270),
        TargetEntityId = 0,
        TargetCurrentHp = 0,
        TargetMaxHp = 0,
        TargetPosition = null,
        TargetServerObjectId = 0,
        WorldObjects = Array.Empty<WorldObjectSnapshot>(),
        Skills = CreateSkillSnapshotsById(new Dictionary<uint, uint>())
    };
    var controller = new StationaryCombatController(keyboard, new SemiAutoCombatController(keyboard));
    var plan = SemiAutoSkillPlan.FromSettings(settings.Skills);
    var state = new StationaryCombatState();
    var semiAutoState = new SemiAutoCombatState();
    var context = CreateContext(settings, gameApi, logger);

    await controller.TickAsync(context, plan, semiAutoState, state).ConfigureAwait(false);

    AssertSequence(new[] { "OemComma" }, keyboard.Keys.ToArray(), "first tick should sit while no targets exist");
    AssertFalse(!state.NoTargetRestActive, "no-target rest should become active");
    keyboard.Keys.Clear();

    gameApi.TargetEntityId = 200;
    gameApi.TargetOwnServerObjectId = 200;
    gameApi.TargetName = "spawned target";
    gameApi.TargetCurrentHp = 1000;
    gameApi.TargetMaxHp = 1000;
    gameApi.TargetPosition = new Vector3Snapshot(5, 0, 0);
    gameApi.TargetServerObjectId = 0;
    gameApi.WorldObjects = new[]
    {
        new WorldObjectSnapshot(200, 200, "spawned target", "monster", new Vector3Snapshot(5, 0, 0), 5, 1000, 1000)
    };

    await controller.TickAsync(context, plan, semiAutoState, state).ConfigureAwait(false);

    AssertSequence(new[] { "X" }, keyboard.Keys.ToArray(), "spawned target should wake no-target rest with x only");
    AssertFalse(keyboard.Keys.Contains("OemComma"), "target wake should not re-enter sit");
    AssertFalse(!state.NoTargetRestActive, "target wake should wait for stand confirmation");
    AssertFalse(!state.NoTargetRestExitPending, "target wake should track pending stand confirmation");
    AssertEqual((ushort)0, state.CandidateEntityId, "target should not become candidate before stand confirmation");
    keyboard.Keys.Clear();

    await controller.TickAsync(context, plan, semiAutoState, state).ConfigureAwait(false);

    AssertFalse(state.NoTargetRestActive, "target wake should clear no-target rest state");
    AssertEqual((ushort)200, state.CandidateEntityId, "spawned target should become the combat candidate");
    AssertFalse(!logger.Entries.Any(entry =>
        entry.EventName == "stationary_combat.no_target.rest_exit" &&
        string.Equals(Convert.ToString(entry.Fields["reason"]), "target_available", StringComparison.Ordinal)),
        "target wake should log no-target rest exit");
    AssertFalse(!logger.Entries.Any(entry =>
        entry.EventName == "stationary_combat.no_target.rest_exit_confirmed" &&
        string.Equals(Convert.ToString(entry.Fields["reason"]), "target_available", StringComparison.Ordinal)),
        "target wake should log stand confirmation");
}

