        AssertFalse(!logger.Entries.Any(entry =>
                entry.EventName == "stationary_combat.recovery_defense.target_selected" &&
                string.Equals(Convert.ToString(entry.Fields["phase"]), "death_recovery", StringComparison.Ordinal)),
            "death recovery defense target should be logged");
    }
    finally
    {
        Environment.SetEnvironmentVariable("ROADHOG_DEATH_REVIVE_CLICK_DELAY_MS", previousClickDelay);
        Environment.SetEnvironmentVariable("ROADHOG_DEATH_REVIVE_MOUSE_STEP_DELAY_MS", previousStepDelay);
        Environment.SetEnvironmentVariable("ROADHOG_DEATH_REVIVE_CLICK_HOLD_MS", previousClickHold);
        Environment.SetEnvironmentVariable("ROADHOG_DEATH_REVIVE_RETRY_MS", previousRetry);
        Environment.SetEnvironmentVariable("ROADHOG_DEATH_POST_REVIVE_SCROLL_INTERVAL_MS", previousScrollInterval);
        Environment.SetEnvironmentVariable("AION_FACE_TARGET_BEARING_MODE", previousBearingMode);
    }
}

static async Task TestStationaryCombatDeathRecoveryPathClearsNearbyAggressiveMonstersAsync()
{
    var previousClickDelay = Environment.GetEnvironmentVariable("ROADHOG_DEATH_REVIVE_CLICK_DELAY_MS");
    var previousStepDelay = Environment.GetEnvironmentVariable("ROADHOG_DEATH_REVIVE_MOUSE_STEP_DELAY_MS");
    var previousClickHold = Environment.GetEnvironmentVariable("ROADHOG_DEATH_REVIVE_CLICK_HOLD_MS");
    var previousRetry = Environment.GetEnvironmentVariable("ROADHOG_DEATH_REVIVE_RETRY_MS");
    var previousScrollInterval = Environment.GetEnvironmentVariable("ROADHOG_DEATH_POST_REVIVE_SCROLL_INTERVAL_MS");
    var previousBearingMode = Environment.GetEnvironmentVariable("AION_FACE_TARGET_BEARING_MODE");
    Environment.SetEnvironmentVariable("ROADHOG_DEATH_REVIVE_CLICK_DELAY_MS", "0");
    Environment.SetEnvironmentVariable("ROADHOG_DEATH_REVIVE_MOUSE_STEP_DELAY_MS", "0");
    Environment.SetEnvironmentVariable("ROADHOG_DEATH_REVIVE_CLICK_HOLD_MS", "1");
    Environment.SetEnvironmentVariable("ROADHOG_DEATH_REVIVE_RETRY_MS", "0");
    Environment.SetEnvironmentVariable("ROADHOG_DEATH_POST_REVIVE_SCROLL_INTERVAL_MS", "0");
    Environment.SetEnvironmentVariable("AION_FACE_TARGET_BEARING_MODE", "y-x");
    try
    {
        var settings = CreateScriptSettings();
        settings.MainMode = AccountMainMode.CustomCombat;
        settings.CombatMode = AccountCombatMode.Stationary;
        settings.Paths.RevivePathName = "revive-a";
        settings.SemiAuto.AttackKeyLoopEnabled = true;
        settings.SemiAuto.AttackKeyLoopIntervalMs = 1;
        settings.Maintenance.SitMaintenanceEnabled = true;
        settings.Maintenance.SitHpRecoverToPercent = 75;
        settings.Combat = new CombatScriptSettings
        {
            HasStationaryCombatPosition = true,
            StationaryCombatX = 20,
            StationaryCombatY = 0,
            StationaryCombatZ = 0,
            StationaryCombatRadius = 10
        };

        var pathStore = new InMemorySharedPathStore(
            CreatePath("revive-a",
                new Vector3Snapshot(0, 0, 0),
                new Vector3Snapshot(10, 0, 0),
                new Vector3Snapshot(20, 0, 0)));
        var keyboard = new RecordingKeyboardInput();
        var logger = new InMemoryRoadhogLogger();
        var gameApi = new FakeGameApi
        {
            Player = new PlayerSnapshot(1, 0, "Fake", 0, 100, 100, 100, 0, new Vector3Snapshot(0, 0, 0), DateTimeOffset.Now, 90, 10, 90),
            TargetEntityId = 0,
            TargetCurrentHp = 0,
            TargetPosition = null,
            WorldObjects = Array.Empty<WorldObjectSnapshot>(),
            Skills = CreateSkillSnapshotsById(new Dictionary<uint, uint>
            {
                [1] = 0,
                [5] = 0,
                [6] = 0
            })
        };
        var semiAuto = new SemiAutoCombatController(keyboard);
        var controller = new StationaryCombatController(keyboard, semiAuto, pathStore);
        var stationaryState = new StationaryCombatState();
        var semiAutoState = new SemiAutoCombatState();
        var plan = SemiAutoSkillPlan.FromSettings(settings.Skills);
        var context = CreateContext(settings, gameApi, logger);

        await controller.TickAsync(context, plan, semiAutoState, stationaryState).ConfigureAwait(false);
        gameApi.Player = gameApi.Player with { CurrentHp = 75 };
        await controller.TickAsync(context, plan, semiAutoState, stationaryState).ConfigureAwait(false);
        await controller.TickAsync(context, plan, semiAutoState, stationaryState).ConfigureAwait(false);

        AssertEqual(StationaryCombatDeathRecoveryStep.FollowRevivePath, stationaryState.DeathRecovery.Step, "revived player should be following revive path");
        AssertFalse(!keyboard.KeyDowns.Contains("W"), "death recovery should start path movement before nearby aggressive monster appears");

        keyboard.Keys.Clear();
        keyboard.KeyUps.Clear();
        gameApi.TargetEntityId = 210;
        gameApi.TargetOwnServerObjectId = 2100;
        gameApi.TargetCurrentHp = 1000;
        gameApi.TargetMaxHp = 1000;
        gameApi.TargetPosition = new Vector3Snapshot(4, 0, 0);
        gameApi.TargetServerObjectId = 0;
        gameApi.TargetIsTargetingLocalPlayer = false;
        gameApi.WorldObjects = new[]
        {
            new WorldObjectSnapshot(
                209,
                2090,
                "passive-near",
                "monster",
                new Vector3Snapshot(2, 0, 0),
                2,
                1000,
                1000,
                AggressiveKnown: true,
                IsAggressiveToPlayer: false),
            new WorldObjectSnapshot(
                210,
                2100,
                "active-near",
                "monster",
                new Vector3Snapshot(4, 0, 0),
                4,
                1000,
                1000,
                AggressiveKnown: true,
                IsAggressiveToPlayer: true),
            new WorldObjectSnapshot(
                211,
                2110,
                "active-outside",
                "monster",
                new Vector3Snapshot(16, 0, 0),
                16,
                1000,
                1000,
                AggressiveKnown: true,
                IsAggressiveToPlayer: true)
        };

        await controller.TickAsync(context, plan, semiAutoState, stationaryState).ConfigureAwait(false);

        AssertEqual(StationaryCombatTopLevelState.DeathRecovery, stationaryState.TopLevelState, "clear should stay inside death recovery path state");
        AssertEqual(StationaryCombatDeathRecoveryStep.FollowRevivePath, stationaryState.DeathRecovery.Step, "clear should not complete revive path");
        AssertFalse(!stationaryState.Fighting, "nearby aggressive monster should interrupt death recovery path into combat");
        AssertFalse(!stationaryState.CurrentTargetIsRevivePathClear, "nearby aggressive monster should be tracked as a revive path clear target");
        AssertFalse(stationaryState.CurrentTargetIsMaintenanceDefense, "nearby aggressive monster should not be treated as targeting-defense yet");
        AssertEqual((ushort)210, stationaryState.CandidateEntityId, "nearest aggressive monster inside default ten meter clear radius should become candidate");
        AssertFalse(!keyboard.KeyUps.Contains("W"), "death recovery clear should stop path movement first");
        AssertFalse(!keyboard.Keys.Contains("C"), "death recovery clear should press the opening attack key while waiting for target aggro");
        AssertFalse(!logger.Entries.Any(entry =>
                entry.EventName == "stationary_combat.recovery_defense.target_selected" &&
                string.Equals(Convert.ToString(entry.Fields["phase"]), "death_recovery", StringComparison.Ordinal) &&
                entry.Fields.TryGetValue("revivePathClear", out var value) &&
                value is true),
            "death recovery clear target should be logged");

        keyboard.Keys.Clear();
        await controller.TickAsync(context, plan, semiAutoState, stationaryState).ConfigureAwait(false);

        AssertFalse(logger.Entries.Any(entry => entry.EventName == "stationary_combat.target.leash_wait"), "revive path clear target should bypass home leash while fighting");
        AssertFalse(!stationaryState.CurrentTargetIsRevivePathClear, "revive path clear flag should remain while fighting the clear target");
    }
    finally
    {
        Environment.SetEnvironmentVariable("ROADHOG_DEATH_REVIVE_CLICK_DELAY_MS", previousClickDelay);
        Environment.SetEnvironmentVariable("ROADHOG_DEATH_REVIVE_MOUSE_STEP_DELAY_MS", previousStepDelay);
        Environment.SetEnvironmentVariable("ROADHOG_DEATH_REVIVE_CLICK_HOLD_MS", previousClickHold);
        Environment.SetEnvironmentVariable("ROADHOG_DEATH_REVIVE_RETRY_MS", previousRetry);
        Environment.SetEnvironmentVariable("ROADHOG_DEATH_POST_REVIVE_SCROLL_INTERVAL_MS", previousScrollInterval);
        Environment.SetEnvironmentVariable("AION_FACE_TARGET_BEARING_MODE", previousBearingMode);
    }
}

static async Task TestStationaryCombatDeathRecoveryPathPostponesRestForNearbyAggressiveAfterLootAsync()
{
    var settings = CreateScriptSettings();
    settings.MainMode = AccountMainMode.CustomCombat;
    settings.CombatMode = AccountCombatMode.Stationary;
    settings.Paths.RevivePathAggressiveClearRadius = 10;
    settings.Maintenance.SitMaintenanceEnabled = true;
    settings.Maintenance.SitHpBelowPercent = 30;
    settings.Maintenance.SitHpRecoverToPercent = 75;
    settings.Combat = new CombatScriptSettings
    {
        EnableLoot = true,
        HasStationaryCombatPosition = true,
        StationaryCombatX = 20,
        StationaryCombatY = 0,
        StationaryCombatZ = 0,
        StationaryCombatRadius = 10
    };

    const ushort aggressiveEntityId = 210;
    const uint aggressiveServerObjectId = 2100;
    var keyboard = new RecordingKeyboardInput();
    var logger = new InMemoryRoadhogLogger();
    var gameApi = new FakeGameApi
    {
        Player = new PlayerSnapshot(
            1,
            0,
            "Fake",
            20,
            100,
            100,
            100,
            0,
            new Vector3Snapshot(0, 0, 0),
            DateTimeOffset.Now),
        TargetEntityId = 0,
        TargetCurrentHp = 0,
        TargetMaxHp = 0,
        TargetPosition = null,
        Skills = CreateSkillSnapshotsById(new Dictionary<uint, uint>()),
        WorldObjects = new[]
        {
            new WorldObjectSnapshot(
                aggressiveEntityId,
                aggressiveServerObjectId,
                "active-near",
                "monster",
                new Vector3Snapshot(4, 0, 0),
                4,
                1000,
                1000,
                AggressiveKnown: true,
                IsAggressiveToPlayer: true)
        }
    };
    var semiAuto = new SemiAutoCombatController(keyboard);
    var controller = new StationaryCombatController(keyboard, semiAuto);
    var stationaryState = new StationaryCombatState();
    stationaryState.EnterDeathRecovery(DateTimeOffset.Now);
    for (var i = 0; i < 7; i++)
    {
        stationaryState.DeathRecovery.Advance(DateTimeOffset.Now);
    }

    stationaryState.StartLootAfterKill(
        new LockedTargetSnapshot(
            100,
            5000,
            0,
            LockedTargetSnapshot.MonsterObjectType,
            "dead-target",
            0,
            100,
            new Vector3Snapshot(2, 0, 0),
            2,
            DateTimeOffset.Now),
        DateTimeOffset.Now);
    stationaryState.LootAfterKill.MoveToPostCombatMaintenance(DateTimeOffset.Now);
    var semiAutoState = new SemiAutoCombatState();

    await controller
        .TickAsync(
            CreateContext(settings, gameApi, logger),
            SemiAutoSkillPlan.FromSettings(settings.Skills),
            semiAutoState,
            stationaryState)
        .ConfigureAwait(false);

    AssertFalse(keyboard.Keys.Contains("OemComma"), "nearby aggressive monster should block death recovery rest before it starts");
    AssertFalse(semiAutoState.IsMaintenanceResting, "blocked death recovery rest should not enter maintenance sitting state");
    AssertFalse(!stationaryState.Fighting, "nearby aggressive monster should become the next death recovery fight");
    AssertFalse(!stationaryState.CurrentTargetIsRevivePathClear, "post-loot aggressive target should be marked as revive path clear");
    AssertFalse(stationaryState.CurrentTargetIsMaintenanceDefense, "generic aggressive target should not be marked as local-side defense");
    AssertEqual(aggressiveEntityId, stationaryState.CurrentTargetEntityId, "post-loot aggressive target entity");
    AssertEqual(aggressiveServerObjectId, stationaryState.CurrentTargetServerObjectId, "post-loot aggressive target server object");
    AssertFalse(stationaryState.LootAfterKill.Active, "loot should finish before the aggressive target handoff");
    AssertFalse(
        !logger.Entries.Any(entry =>
            entry.EventName == "stationary_combat.loot.post_combat_maintenance_postponed" &&
            entry.Fields.TryGetValue("revivePathClear", out var value) &&
            value is true),
        "death recovery post-loot rest postponement should identify revive path clear target");
}

static async Task TestStationaryCombatDeathRecoveryAdoptsPetFightPreAimAfterLootAsync()
{
    var settings = CreateScriptSettings();
    settings.MainMode = AccountMainMode.CustomCombat;
    settings.CombatMode = AccountCombatMode.Stationary;
    settings.Paths.RevivePathAggressiveClearRadius = 12;
    settings.Maintenance.SitMaintenanceEnabled = true;
    settings.Maintenance.SitHpBelowPercent = 30;
    settings.Maintenance.SitHpRecoverToPercent = 75;
    settings.Combat = new CombatScriptSettings
    {
        EnableLoot = true,
        SmartPreAimEnabled = true,
        HasStationaryCombatPosition = true,
        StationaryCombatX = 100,
        StationaryCombatY = 0,
        StationaryCombatZ = 0,
        StationaryCombatRadius = 10
    };

    const ushort targetEntityId = 240;
    const uint targetServerObjectId = 2400;
    var petFightTarget = new WorldObjectSnapshot(
        targetEntityId,
        targetServerObjectId,
        "pet-fight-pre-aim",
        "monster",
        new Vector3Snapshot(20, 0, 0),
        20,
        1000,
        1000,
        TargetServerObjectId: 0,
        IsTargetingLocalPlayer: false,
        AggressiveKnown: true,
        IsAggressiveToPlayer: false);
    var keyboard = new RecordingKeyboardInput();
    var logger = new InMemoryRoadhogLogger();
    var gameApi = new FakeGameApi
    {
        Player = new PlayerSnapshot(
            1,
            0,
            "Fake",
            20,
            100,
            100,
            100,
            0,
            new Vector3Snapshot(0, 0, 0),
            DateTimeOffset.Now),
        TargetEntityId = 0,
        TargetCurrentHp = 0,
        TargetMaxHp = 0,
        TargetPosition = null,
        Skills = CreateSkillSnapshotsById(new Dictionary<uint, uint>()),
        WorldObjects = new[] { petFightTarget }
    };
    var controller = new StationaryCombatController(
        keyboard,
        new SemiAutoCombatController(keyboard));
    var state = new StationaryCombatState();
    state.EnterDeathRecovery(DateTimeOffset.Now);
    for (var i = 0; i < 7; i++)
    {
        state.DeathRecovery.Advance(DateTimeOffset.Now);
    }

    state.StartLootAfterKill(
        new LockedTargetSnapshot(
            100,
            5000,
            0,
            LockedTargetSnapshot.MonsterObjectType,
            "dead-target",
            0,
            100,
            new Vector3Snapshot(2, 0, 0),
            2,
            DateTimeOffset.Now),
        DateTimeOffset.Now);
    state.LootAfterKill.MoveToPostCombatMaintenance(DateTimeOffset.Now);
    SeedAlignedSmartPreAimCandidate(state, petFightTarget);
    state.NextTargetPreAim.TargetingLocalSide = true;

    await controller
        .TickAsync(
            CreateContext(settings, gameApi, logger),
            SemiAutoSkillPlan.FromSettings(settings.Skills),
            new SemiAutoCombatState(),
            state)
        .ConfigureAwait(false);

    AssertFalse(!state.Fighting, "the retained pet-fight pre-aim target should enter combat before revive-path maintenance or movement");
    AssertEqual(targetEntityId, state.CurrentTargetEntityId, "post-loot pet-fight handoff entity");
    AssertEqual(targetServerObjectId, state.CurrentTargetServerObjectId, "post-loot pet-fight handoff server identity");
    AssertFalse(state.LootAfterKill.Active, "pet-fight handoff should finish the old corpse loot flow");
    AssertFalse(!state.CurrentTargetIsRevivePathClear, "a retained pet-fight target without a current reverse target relation should remain a revive-path clear target");
    AssertFalse(state.CurrentTargetIsMaintenanceDefense, "stale positive pet-fight evidence must not fabricate a current targeting relation");
    AssertFalse(keyboard.Keys.Contains("OemComma"), "pet-fight handoff should preempt post-loot sitting");
    AssertFalse(keyboard.KeyDowns.Contains("W"), "pet-fight handoff should not resume the revive path");
    AssertFalse(!logger.Entries.Any(entry =>
            entry.EventName == "stationary_combat.loot.post_combat_maintenance_postponed" &&
            entry.Fields.TryGetValue("smartPreAimHandoff", out var value) &&
            value is true &&
            Convert.ToUInt32(entry.Fields["targetServerObjectId"]) == targetServerObjectId),
        "post-loot handoff should log the retained smart pre-aim identity");
    AssertFalse(!logger.Entries.Any(entry =>
            entry.EventName == "stationary_combat.smart_preaim.handoff_completed" &&
            Convert.ToUInt32(entry.Fields["targetServerObjectId"]) == targetServerObjectId),
        "direct post-loot adoption should complete and clear the smart pre-aim handoff");
}

static async Task TestStationaryCombatDeathRecoveryHoldsPathForMissingPetFightPreAimAsync()
{
    var previousBearingMode = Environment.GetEnvironmentVariable("AION_FACE_TARGET_BEARING_MODE");
    Environment.SetEnvironmentVariable("AION_FACE_TARGET_BEARING_MODE", "y-x");
    try
    {
        var settings = CreateScriptSettings();
        settings.MainMode = AccountMainMode.CustomCombat;
        settings.CombatMode = AccountCombatMode.Stationary;
        settings.Paths.RevivePathAggressiveClearRadius = 12;
        settings.Combat = new CombatScriptSettings
        {
            SmartPreAimEnabled = true,
            HasStationaryCombatPosition = true,
            StationaryCombatX = 100,
            StationaryCombatY = 0,
            StationaryCombatZ = 0,
            StationaryCombatRadius = 10
        };

        var missingTarget = new WorldObjectSnapshot(
            241,
            2401,
            "missing-pet-fight-pre-aim",
            "monster",
            new Vector3Snapshot(20, 0, 0),
            20,
            1000,
            1000);
        var keyboard = new RecordingKeyboardInput();
        var logger = new InMemoryRoadhogLogger();
        var gameApi = new FakeGameApi
        {
            Player = new PlayerSnapshot(
                1,
                0,
                "Fake",
                100,
                100,
                100,
                100,
                0,
                new Vector3Snapshot(0, 0, 0),
                DateTimeOffset.Now,
                90,
                10,
                90),
            TargetEntityId = 0,
            TargetCurrentHp = 0,
            TargetMaxHp = 0,
            TargetPosition = null,
            Skills = CreateSkillSnapshotsById(new Dictionary<uint, uint>()),
            WorldObjects = Array.Empty<WorldObjectSnapshot>()
        };
        var controller = new StationaryCombatController(
            keyboard,
            new SemiAutoCombatController(keyboard));
        var state = new StationaryCombatState();
        state.EnterDeathRecovery(DateTimeOffset.Now);
        for (var i = 0; i < 7; i++)
        {
            state.DeathRecovery.Advance(DateTimeOffset.Now);
        }

        state.DeathRecovery.RevivePathName = "revive-a";
        state.DeathRecovery.RevivePathPoints = new[]
        {
            new Vector3Snapshot(0, 0, 0),
            new Vector3Snapshot(50, 0, 0)
        };
        state.DeathRecovery.RevivePathPointIndex = 1;
        var context = CreateContext(settings, gameApi, logger);
        var plan = SemiAutoSkillPlan.FromSettings(settings.Skills);
        var semiAutoState = new SemiAutoCombatState();

        await controller.TickAsync(context, plan, semiAutoState, state).ConfigureAwait(false);
        AssertFalse(!state.IsMovingForward, "revive path should be moving before the retained target becomes unavailable");

        SeedAlignedSmartPreAimCandidate(state, missingTarget);
        state.NextTargetPreAim.TargetingLocalSide = true;
        keyboard.Keys.Clear();
        keyboard.KeyUps.Clear();
        var pathFollowCount = logger.Entries.Count(entry =>
            entry.EventName == "stationary_combat.death_recovery.path_follow");

        await controller.TickAsync(context, plan, semiAutoState, state).ConfigureAwait(false);

        AssertFalse(state.HasSmartPreAimHandoff, "trusted missing snapshot should release the recovery handoff immediately");
        AssertFalse(state.NextTargetPreAim.HasCandidate, "trusted missing recovery target should clear the retained pre-aim result");
        AssertFalse(
            logger.Entries.Count(entry => entry.EventName == "stationary_combat.death_recovery.path_follow") < pathFollowCount,
            "released handoff may resume the revive path immediately");
        AssertFalse(keyboard.Keys.Contains("Tab"), "a missing committed target must not Tab stale identity");
        AssertFalse(keyboard.Keys.Any(key => key.StartsWith("D", StringComparison.OrdinalIgnoreCase)), "a missing committed target must not attack stale coordinates");
    }
    finally
    {
        Environment.SetEnvironmentVariable("AION_FACE_TARGET_BEARING_MODE", previousBearingMode);
    }
}

