            {
                new WorldObjectSnapshot(
                    220,
                    2200,
                    "path-passive-inside-five",
                    "monster",
                    new Vector3Snapshot(4, 0, 0),
                    4,
                    1000,
                    1000,
                    AggressiveKnown: true,
                    IsAggressiveToPlayer: false)
            },
