    {
        Player = CreateSpiritmasterPlayer(),
        SummonedPetRoster = SummonedPetRosterSnapshot.Empty(1000, DateTimeOffset.Now),
        TargetEntityId = 0,
        TargetCurrentHp = 0,
        TargetPosition = null,
        Skills = CreateSpiritmasterSkillSnapshots()
    };
    var semiAuto = new SemiAutoCombatController(keyboard);
