            TargetCurrentHp = 1000,
            TargetPosition = new Vector3Snapshot(40, 0, 0),
            WorldObjects = new[]
            {
                new WorldObjectSnapshot(100, 100, "target", "monster", new Vector3Snapshot(40, 0, 0), 40, 1000, 1000)
            },
