        CurrentTargetEntityId = 100,
        CurrentTargetServerObjectId = targetServerObjectId,
        CandidateEntityId = 100,
        CandidateServerObjectId = targetServerObjectId,
        LocalCombatSideServerObjectId = localServerObjectId
    };
