        };
        var semiAuto = new SemiAutoCombatController(keyboard);
        var controller = new StationaryCombatController(keyboard, semiAuto, pathStore);
        var state = new StationaryCombatState();
        state.StartLootAfterKill(
            new LockedTargetSnapshot(
                100,
                5000,
                0,
                LockedTargetSnapshot.MonsterObjectType,
                "dead-target",
                0,
                100,
                new Vector3Snapshot(0, 0, 0),
                0,
                DateTimeOffset.Now),
            DateTimeOffset.Now);
        for (var i = 0; i < 5; i++)
        {
            state.LootAfterKill.Advance(DateTimeOffset.Now);
        }

        state.StartCleanupReturnToCombat();

        await controller
            .TickAsync(CreateContext(settings, gameApi, logger), SemiAutoSkillPlan.FromSettings(settings.Skills), new SemiAutoCombatState(), state)
            .ConfigureAwait(false);

        AssertFalse(!state.CleanupReturnToCombatActive, "cleanup return should stay active while revive path is still running");
        AssertFalse(!state.StartupRecoveryActive, "cleanup return should reuse startup recovery revive-path following");
        AssertEqual("revive-a", state.StartupRecoveryPathName, "cleanup return should use configured revive path");
        AssertEqual(1, state.StartupRecoveryPointIndex, "cleanup return should advance from reached camp point toward combat home");
        AssertFalse(!state.LootAfterKill.Active, "loot should remain active until cleanup return reaches combat home");
        AssertFalse(logger.Entries.Any(entry => entry.EventName == "stationary_combat.loot.finished"),
            "loot should not finish before cleanup return-to-combat recovery completes");
        AssertFalse(!logger.Entries.Any(entry => entry.EventName == "stationary_combat.startup_recovery.selected"),
            "cleanup return should start revive-path recovery");
    }
    finally
    {
        Environment.SetEnvironmentVariable("AION_FACE_TARGET_BEARING_MODE", previousBearingMode);
    }
}

static async Task TestStationaryCombatRefreshesPositionAfterBagCleanupReturnAsync()
{
    var previousBearingMode = Environment.GetEnvironmentVariable("AION_FACE_TARGET_BEARING_MODE");
    Environment.SetEnvironmentVariable("AION_FACE_TARGET_BEARING_MODE", "y-x");
    try
    {
        var settings = CreateScriptSettings();
        settings.MainMode = AccountMainMode.CustomCombat;
        settings.CombatMode = AccountCombatMode.Path;
        settings.Paths.RevivePathName = "revive-a";
        settings.Paths.CombatPathName = "combat-a";
        settings.Combat = new CombatScriptSettings
        {
            EnableLoot = true,
            StationaryCombatRadius = 20,
            PathFollowReachDistance = 5
        };

        var cleanupPath = CreatePath(
            "cleanup-a",
            new Vector3Snapshot(0, 0, 0),
            new Vector3Snapshot(100, 0, 0));
        var pathStore = new InMemorySharedPathStore(
            cleanupPath,
            CreatePath(
                "revive-a",
                new Vector3Snapshot(0, 0, 0),
                new Vector3Snapshot(100, 0, 0),
                new Vector3Snapshot(200, 0, 0)),
            CreatePath(
                "combat-a",
                new Vector3Snapshot(205, 0, 0),
                new Vector3Snapshot(215, 0, 0)));
        var staleCleanupPosition = new PlayerSnapshot(
            1,
            100,
            "Fake",
            100,
            100,
            100,
            100,
            0,
            new Vector3Snapshot(100, 0, 0),
            DateTimeOffset.Now,
            90,
            10,
            90);
        var freshReturnPosition = staleCleanupPosition with
        {
            Position = new Vector3Snapshot(0, 0, 0),
            CapturedAt = DateTimeOffset.Now
        };
        var gameApi = new FakeGameApi
        {
            Player = freshReturnPosition,
            TargetEntityId = 0,
            TargetCurrentHp = 0,
            TargetMaxHp = 0,
            TargetPosition = null,
            WorldObjects = Array.Empty<WorldObjectSnapshot>(),
            Skills = CreateSkillSnapshotsById(new Dictionary<uint, uint>())
        };
        gameApi.PlayerReadResults.Enqueue(OperationResult<PlayerSnapshot>.Ok(staleCleanupPosition));
        gameApi.PlayerReadResults.Enqueue(OperationResult<PlayerSnapshot>.Ok(staleCleanupPosition));
        gameApi.PlayerReadResults.Enqueue(OperationResult<PlayerSnapshot>.Ok(staleCleanupPosition));
        gameApi.PlayerReadResults.Enqueue(OperationResult<PlayerSnapshot>.Ok(freshReturnPosition));

        var keyboard = new RecordingKeyboardInput();
        var logger = new InMemoryRoadhogLogger();
        var controller = new StationaryCombatController(
            keyboard,
            new SemiAutoCombatController(keyboard),
            pathStore);
        var state = new StationaryCombatState();
        state.StartLootAfterKill(
            new LockedTargetSnapshot(
                100,
                5000,
                0,
                LockedTargetSnapshot.MonsterObjectType,
                "dead-target",
                0,
                100,
                new Vector3Snapshot(0, 0, 0),
                0,
                DateTimeOffset.Now),
            DateTimeOffset.Now);
        for (var i = 0; i < 5; i++)
        {
            state.LootAfterKill.Advance(DateTimeOffset.Now);
        }

        state.BagCleanup.Start(0, 2);
        state.BagCleanup.SetPath(cleanupPath);
        state.BagCleanup.ReturnAfterFailure("simulated_cleanup_failure", "simulated cleanup failure");
        var context = CreateContext(settings, gameApi, logger);
        var plan = SemiAutoSkillPlan.FromSettings(settings.Skills);
        var semiAutoState = new SemiAutoCombatState();

        await controller
            .TickAsync(context, plan, semiAutoState, state)
            .ConfigureAwait(false);

        AssertFalse(!state.CleanupReturnToCombatActive, "cleanup return should wait for the next fresh player snapshot");
        AssertFalse(state.StartupRecoveryActive, "stale pre-return player position must not start revive-path recovery");
        AssertFalse(
            logger.Entries.Any(entry => entry.EventName == "stationary_combat.startup_recovery.selected"),
            "stale pre-return player position must not select a revive-path point");

        await controller
            .TickAsync(context, plan, semiAutoState, state)
            .ConfigureAwait(false);

        AssertFalse(!state.StartupRecoveryActive, "fresh post-return player position should start revive-path recovery");
        AssertEqual(1, state.StartupRecoveryPointIndex, "fresh route-start position should advance from the first revive-path point");
        AssertFalse(
            !logger.Entries.Any(entry =>
                entry.EventName == "stationary_combat.startup_recovery.selected" &&
                entry.Fields.TryGetValue("startPointIndex", out var index) &&
                Convert.ToInt32(index) == 0),
            "fresh post-return position should select the first revive-path point");
    }
    finally
    {
        Environment.SetEnvironmentVariable("AION_FACE_TARGET_BEARING_MODE", previousBearingMode);
    }
}

static async Task TestStationaryCombatPostponesAfterCombatMaintenanceWhilePetIsTargetedAsync()
{
    var previousAfterKillWait = Environment.GetEnvironmentVariable("ROADHOG_LOOT_AFTER_KILL_WAIT_MS");
    var previousWait = Environment.GetEnvironmentVariable("ROADHOG_LOOT_AFTER_PICK_WAIT_MS");
    var previousPressCount = Environment.GetEnvironmentVariable("ROADHOG_LOOT_PRESS_COUNT");
    var previousPressInterval = Environment.GetEnvironmentVariable("ROADHOG_LOOT_PRESS_INTERVAL_MS");
    Environment.SetEnvironmentVariable("ROADHOG_LOOT_AFTER_KILL_WAIT_MS", "0");
    Environment.SetEnvironmentVariable("ROADHOG_LOOT_AFTER_PICK_WAIT_MS", "0");
    Environment.SetEnvironmentVariable("ROADHOG_LOOT_PRESS_COUNT", null);
    Environment.SetEnvironmentVariable("ROADHOG_LOOT_PRESS_INTERVAL_MS", "0");
    try
    {
        const ushort defenseEntityId = 200;
        const uint defenseServerObjectId = 2200;
        const uint petServerObjectId = 2000;
        var settings = CreateSpiritmasterScriptSettings();
        settings.MainMode = AccountMainMode.CustomCombat;
        settings.CombatMode = AccountCombatMode.Stationary;
        settings.Combat = new CombatScriptSettings
        {
            EnableLoot = true,
            HasStationaryCombatPosition = true,
            StationaryCombatX = 0,
            StationaryCombatY = 0,
            StationaryCombatZ = 0,
            StationaryCombatRadius = 60
        };
        settings.Maintenance.SitMaintenanceEnabled = false;
        settings.Maintenance.HpMaintenanceRules.Add(new MaintenanceKeyRuleConfig
        {
            BelowPercent = 50,
            Key = "D8",
            RunTiming = MaintenanceRuleRunTiming.AfterCombat
        });

        var keyboard = new RecordingKeyboardInput();
        var logger = new InMemoryRoadhogLogger();
        var gameApi = new FakeGameApi
        {
            Player = new PlayerSnapshot(
                1,
                100,
                "Spirit",
                40,
                100,
                100,
                100,
                0,
                new Vector3Snapshot(0, 0, 0),
                DateTimeOffset.Now,
                CharacterClass: AionClassCatalog.GetChineseName(AionClassId.Spiritmaster),
                CharacterClassId: AionClassId.Spiritmaster),
            SummonedPetRoster = CreateLocalPetRoster(isSummoned: true),
            TargetEntityId = 100,
            TargetCurrentHp = 0,
            TargetMaxHp = 4430,
            TargetPosition = new Vector3Snapshot(2.5f, 0, 0),
            Skills = CreateSpiritmasterSkillSnapshots(),
            WorldObjects = new[]
            {
                new WorldObjectSnapshot(
                    defenseEntityId,
                    defenseServerObjectId,
                    "pet-targeting",
                    "monster",
                    new Vector3Snapshot(8, 0, 0),
                    8,
                    1000,
                    1000,
                    petServerObjectId,
                    false)
            }
        };

        var semiAuto = new SemiAutoCombatController(keyboard);
        var controller = new StationaryCombatController(keyboard, semiAuto);
        var plan = SemiAutoSkillPlan.FromSettings(settings.Skills);
        var semiAutoState = new SemiAutoCombatState();
        CalibrateCooldownClock(semiAutoState);
        var state = new StationaryCombatState
        {
            Fighting = true,
            CurrentTargetEntityId = 100,
            CandidateEntityId = 100
        };

        await controller
            .TickAsync(CreateContext(settings, gameApi, logger), plan, semiAutoState, state)
            .ConfigureAwait(false);

        AssertFalse(keyboard.Keys.Contains("D8"), "after-combat maintenance should wait while another monster targets the pet");
        AssertSequence(new[] { "NumPadDecimal" }, keyboard.Keys, "loot should still be pressed for the killed monster");
        AssertFalse(state.LootAfterKill.Active, "loot state should finish before switching to defense target");
        AssertFalse(!state.Fighting, "defense target should become the next fight");
        AssertFalse(!state.CurrentTargetIsMaintenanceDefense, "pet-targeting monster should be marked as local-side defense");
        AssertEqual(defenseEntityId, state.CurrentTargetEntityId, "defense target entity");
        AssertEqual(defenseServerObjectId, state.CurrentTargetServerObjectId, "defense target server object");
        AssertFalse(
            !logger.Entries.Any(entry => entry.EventName == "stationary_combat.loot.post_combat_maintenance_postponed"),
            "post-combat maintenance should log postponement");
    }
    finally
    {
        Environment.SetEnvironmentVariable("ROADHOG_LOOT_AFTER_KILL_WAIT_MS", previousAfterKillWait);
        Environment.SetEnvironmentVariable("ROADHOG_LOOT_AFTER_PICK_WAIT_MS", previousWait);
        Environment.SetEnvironmentVariable("ROADHOG_LOOT_PRESS_COUNT", previousPressCount);
        Environment.SetEnvironmentVariable("ROADHOG_LOOT_PRESS_INTERVAL_MS", previousPressInterval);
    }
}

static async Task TestStationaryCombatAbandonsDiscardBeforeAdoptingDefenseTargetAsync()
{
    var settings = CreateScriptSettings();
    settings.MainMode = AccountMainMode.CustomCombat;
    settings.CombatMode = AccountCombatMode.Stationary;
    settings.Combat = new CombatScriptSettings
    {
        EnableLoot = true,
        HasStationaryCombatPosition = true,
        StationaryCombatX = 0,
        StationaryCombatY = 0,
        StationaryCombatZ = 0,
        StationaryCombatRadius = 30
    };
    settings.Maintenance.SitMaintenanceEnabled = false;

    const uint discardInstanceId = 40;
    const ushort defenseEntityId = 200;
    const uint defenseServerObjectId = 2200;
    var discardTarget = new InventoryItemSnapshot(167000450, discardInstanceId, "discard-target", 1, 0, false, 24, 2);
    var keyboard = new RecordingKeyboardInput();
    var logger = new InMemoryRoadhogLogger();
    var gameApi = new FakeGameApi
    {
        Player = new PlayerSnapshot(
            1,
            100,
            "Fake",
            100,
            100,
            100,
            100,
            0,
            new Vector3Snapshot(0, 0, 0),
            DateTimeOffset.Now),
        TargetEntityId = 0,
        TargetCurrentHp = 0,
        TargetMaxHp = 0,
        TargetPosition = null,
        InventoryCapacity = 3,
        InventoryItems = new[] { discardTarget },
        InventoryWindow = CreateInventoryWindow(true, 0.0, 0.0),
        InventoryDiscardConfirm = new InventoryDiscardConfirmSnapshot(
            false,
            discardInstanceId,
            InventoryDiscardConfirmKind.PendingWithoutVisibleDialog,
            0,
            0,
            DateTimeOffset.Now),
        Skills = CreateSkillSnapshotsById(new Dictionary<uint, uint>()),
        WorldObjects = new[]
        {
            new WorldObjectSnapshot(
                defenseEntityId,
                defenseServerObjectId,
                "attacker",
                "monster",
                new Vector3Snapshot(5, 0, 0),
                5,
                1000,
                1000,
                TargetServerObjectId: 100,
                IsTargetingLocalPlayer: true)
        }
    };
    keyboard.AfterPress = key =>
    {
        if (string.Equals(key, "Escape", StringComparison.Ordinal))
        {
            gameApi.InventoryDiscardConfirm = InventoryDiscardConfirmSnapshot.Closed(DateTimeOffset.Now);
        }
        else if (string.Equals(key, "I", StringComparison.Ordinal))
        {
            gameApi.InventoryWindow = CreateInventoryWindow(false, 0.0, 0.0);
        }
    };

    var controller = new StationaryCombatController(
        keyboard,
        new SemiAutoCombatController(keyboard),
        new InMemorySharedPathStore());
    var state = new StationaryCombatState();
    state.StartLootAfterKill(
        new LockedTargetSnapshot(
            100,
            5000,
            0,
            LockedTargetSnapshot.MonsterObjectType,
            "dead-target",
            0,
            100,
            new Vector3Snapshot(0, 0, 0),
            0,
            DateTimeOffset.Now),
        DateTimeOffset.Now);
    for (var i = 0; i < 5; i++)
    {
        state.LootAfterKill.Advance(DateTimeOffset.Now);
    }

    state.BagCleanup.StartDiscard(1, 2, 1);
    state.BagCleanup.SetDiscardWindow(gameApi.InventoryWindow);
    state.BagCleanup.SetDiscardTarget(discardTarget);
    state.BagCleanup.Advance(BagCleanupStep.WaitDiscardConfirm);

    await controller
        .TickAsync(
            CreateContext(settings, gameApi, logger),
            SemiAutoSkillPlan.FromSettings(settings.Skills),
            new SemiAutoCombatState(),
            state)
        .ConfigureAwait(false);

    AssertFalse(gameApi.InventoryWindow.IsOpen, "defense handoff should close inventory before combat");
    AssertFalse(state.BagCleanup.Active, "defense handoff should abandon the current discard session");
    AssertFalse(!gameApi.InventoryItems.Any(item => item.InstanceId == discardInstanceId), "pre-confirm interruption must keep the item");
    AssertFalse(!keyboard.Keys.Contains("Escape"), "pre-confirm interruption should cancel the pending discard");
    AssertFalse(!keyboard.Keys.Contains("I"), "pre-confirm interruption should close inventory");
    AssertEqual(defenseEntityId, state.CurrentTargetEntityId, "defense target should be adopted after discard is closed");
    AssertFalse(!state.CurrentTargetIsMaintenanceDefense, "defense target should be marked as maintenance defense");
    AssertFalse(
        !logger.Entries.Any(entry => entry.EventName == "bag_cleanup.discard.interrupted_by_attack"),
        "discard interruption should be logged before combat handoff");
}

static async Task TestStationaryCombatClosesDiscardBeforeDeathRecoveryAsync()
{
    var settings = CreateDiscardScriptSettings(BagCleanupRuleCatalog.GreenManastone, threshold: 2);
    settings.MainMode = AccountMainMode.CustomCombat;
    settings.CombatMode = AccountCombatMode.Stationary;
    const uint discardInstanceId = 44;
    var discardTarget = new InventoryItemSnapshot(
        167000450,
        discardInstanceId,
        "discard-target",
        1,
        0,
        false,
        24,
        2);
    var keyboard = new RecordingKeyboardInput();
    var logger = new InMemoryRoadhogLogger();
    var gameApi = CreateSafeDiscardGameApi(capacity: 3, discardTarget);
    gameApi.Player = new PlayerSnapshot(
        1,
        100,
        "Fake",
        0,
        100,
        100,
        100,
        0,
        new Vector3Snapshot(0, 0, 0),
        DateTimeOffset.Now);
    gameApi.InventoryWindow = CreateInventoryWindow(true, 0.0, 0.0);
    gameApi.InventoryDiscardConfirm = new InventoryDiscardConfirmSnapshot(
        true,
        discardInstanceId,
        InventoryDiscardConfirmKind.Normal,
        336,
        0x4567,
        DateTimeOffset.Now);
    var confirmMouseDown = false;
    keyboard.AfterMouseDown = button =>
    {
        if (button == RoadhogMouseButton.Left && gameApi.InventoryDiscardConfirm.IsOpen)
        {
            confirmMouseDown = true;
        }
    };
    keyboard.AfterMouseUp = button =>
    {
        if (button != RoadhogMouseButton.Left || !confirmMouseDown)
        {
            return;
        }

        confirmMouseDown = false;
        gameApi.InventoryItems = gameApi.InventoryItems
            .Where(item => item.InstanceId != discardInstanceId)
            .ToArray();
        gameApi.InventoryDiscardConfirm = InventoryDiscardConfirmSnapshot.Closed(DateTimeOffset.Now);
    };
    keyboard.AfterPress = key =>
    {
        if (key == "I")
        {
            gameApi.InventoryWindow = CreateInventoryWindow(false, 0.0, 0.0);
        }
    };
    var controller = new StationaryCombatController(
        keyboard,
        new SemiAutoCombatController(keyboard),
        new InMemorySharedPathStore());
    var state = new StationaryCombatState();
    state.BagCleanup.StartDiscard(1, 2, 1);
    state.BagCleanup.SetDiscardWindow(gameApi.InventoryWindow);
    state.BagCleanup.SetDiscardTarget(discardTarget);
    state.BagCleanup.Advance(BagCleanupStep.WaitDiscardConfirm);

    await controller
        .TickPlayerLifeGuardAsync(
            CreateContext(settings, gameApi, logger),
            SemiAutoSkillPlan.FromSettings(settings.Skills),
            new SemiAutoCombatState(),
            state,
            followRevivePath: false)
        .ConfigureAwait(false);

    AssertEqual(StationaryCombatTopLevelState.DeathRecovery, state.TopLevelState, "death recovery should start after discard shutdown");
    AssertFalse(state.BagCleanup.Active, "death recovery should not preserve a resumable discard session");
    AssertFalse(gameApi.InventoryItems.Any(item => item.InstanceId == discardInstanceId), "visible confirm should be completed before death recovery");
    AssertFalse(gameApi.InventoryWindow.IsOpen, "inventory should close before death recovery continues");
    AssertFalse(!keyboard.MouseCommands.Contains("move:650,470"), "death handoff should click the configured discard confirm point");
    AssertFalse(
        !logger.Entries.Any(entry =>
            entry.EventName == "bag_cleanup.discard.interrupted" &&
            string.Equals(Convert.ToString(entry.Fields["interruptionReason"]), "death_recovery", StringComparison.Ordinal)),
        "death discard shutdown should be logged");
}

