static SummonedPetRosterSnapshot CreateLocalPetRoster(
    bool isSummoned,
    byte hpPercent = 100,
    IReadOnlyList<AbnormalStatusEntrySnapshot>? abnormalStatuses = null,
    uint? currentHp = null,
    uint maxHp = 100,
    bool currentHpAvailable = true,
    bool maxHpAvailable = true,
    bool hpPercentAvailable = true,
    DateTimeOffset? capturedAt = null,
    uint petServerObjectId = 2000)
{
    var now = capturedAt ?? DateTimeOffset.Now;
    const uint localServerObjectId = 1000;
    var resolvedCurrentHp = currentHp ?? (uint)Math.Round(maxHp * hpPercent / 100.0D);
    var resolvedHpPercent = maxHp == 0
        ? hpPercent
        : (byte)Math.Clamp((int)Math.Round(resolvedCurrentHp * 100.0D / maxHp), 0, 100);
    var pet = isSummoned
        ? new SummonedPetSnapshot(
            true,
            2,
            petServerObjectId,
            0,
            SummonedPetSnapshot.ActorObjectType,
            0,
            "Pet",
            "Pet",
            "pet",
            "pet",
            50,
            resolvedCurrentHp,
            maxHp,
            resolvedHpPercent,
            new Vector3Snapshot(1, 0, 0),
            1,
            localServerObjectId,
            now,
            petServerObjectId,
            true,
            "test",
            new SummonedPetHealthFieldValidity(
                currentHpAvailable,
                maxHpAvailable,
                hpPercentAvailable))
        : SummonedPetSnapshot.NotSummoned(localServerObjectId, now);

    return new SummonedPetRosterSnapshot(
        localServerObjectId,
        isSummoned ? petServerObjectId : 0,
        now,
        new OwnedSummonedPetSnapshot(
            SummonedPetOwnerKind.LocalPlayer,
            localServerObjectId,
            "Spirit",
            "Spirit",
            pet,
            0,
            abnormalStatuses ?? Array.Empty<AbnormalStatusEntrySnapshot>(),
            OwnerClassId: AionClassId.Spiritmaster,
            OwnerClassName: AionClassCatalog.GetChineseName(AionClassId.Spiritmaster)),
        Array.Empty<OwnedSummonedPetSnapshot>(),
        Array.Empty<uint>());
}

