static Task TestDmaWorldSnapshotMergesFieldFailuresAsync()
{
    var previousTarget = new WorldObjectSnapshot(
        10,
        1000,
        "target",
        "monster",
        new Vector3Snapshot(5, 0, 0),
        5,
        CurrentHp: 90,
