        LootableRaw: 0,
        InteractionState: 41);
    var previousMissing = new WorldObjectSnapshot(
        11,
        1001,
        "temporarily missing",
        "monster",
        new Vector3Snapshot(8, 0, 0),
        8,
        CurrentHp: 50,
        MaxHp: 50);
    var observed = previousTarget with
    {
        Position = new Vector3Snapshot(4, 0, 0),
        DistanceToLocalPlayer = 4,
        CurrentHp = 0,
        MaxHp = 120,
        TargetServerObjectId = 8000,
        IsTargetingLocalPlayer = false,
        LootableRaw = 1,
        InteractionState = 37
    };
    var now = new DateTimeOffset(2026, 8, 15, 1, 0, 0, TimeSpan.Zero);
    var read = new WorldObjectReadResult(
        WorldObjectReadCompleteness.Partial,
        new[]
        {
            new WorldObjectObservation(
                observed,
                new WorldObjectFieldValidity(
                    CurrentHp: false,
                    MaxHp: true,
                    TargetServerObjectId: true,
                    IsTargetingLocalPlayer: false,
                    LootableRaw: true,
                    InteractionState: true))
        },
        CreateDmaWorldReadDiagnostics(now));

    var merged = AionVmmGameApi.MergeWorldObjectRead(read, new[] { previousTarget, previousMissing });
    var target = merged.Single(item => item.ServerObjectId == previousTarget.ServerObjectId);

    AssertEqual(2, merged.Count, "partial traversal should retain temporarily missing objects");
    AssertEqual(90u, target.CurrentHp, "failed current hp should use last good");
    AssertEqual(120u, target.MaxHp, "successful max hp should update");
    AssertEqual(8000u, target.TargetServerObjectId, "successful target id should update");
    AssertFalse(!target.IsTargetingLocalPlayer, "failed targeting flag should use last good");
    AssertEqual(1u, target.LootableRaw, "successful loot field should update");
    AssertEqual(37u, target.InteractionState, "successful interaction field should update");
    AssertEqual(4D, target.DistanceToLocalPlayer ?? double.NaN, "non-failed position data should update");
    return Task.CompletedTask;
}

static Task TestDmaWorldPartialSnapshotIsPublishedAndFailedReadHoldsItAsync()
{
    var api = new AionVmmGameApi(new AionVmmGameApiOptions(), NoOpRoadhogLogger.Instance);
    var context = CreateDmaSnapshotContext();
    var startedAt = new DateTimeOffset(2026, 8, 15, 1, 0, 0, TimeSpan.Zero);
    var initialTarget = new WorldObjectSnapshot(
        10,
        1000,
        "target",
        "monster",
        new Vector3Snapshot(5, 0, 0),
        5,
        CurrentHp: 90,
        MaxHp: 100,
        TargetServerObjectId: 7000,
        IsTargetingLocalPlayer: true,
        LootableRaw: 0,
        InteractionState: 41);
    var temporarilyMissing = new WorldObjectSnapshot(
        11,
        1001,
        "temporarily missing",
        "monster",
        new Vector3Snapshot(8, 0, 0),
        8,
        CurrentHp: 50,
        MaxHp: 50);
    var completeFields = new WorldObjectFieldValidity(true, true, true, true, true, true);
    var complete = new WorldObjectReadResult(
        WorldObjectReadCompleteness.Complete,
        new[]
        {
            new WorldObjectObservation(initialTarget, completeFields),
            new WorldObjectObservation(temporarilyMissing, completeFields)
        },
        CreateDmaWorldReadDiagnostics(startedAt));

    var initial = api.StabilizeWorldObjectRead(context, complete, startedAt);
    AssertFalse(!initial.Success, "complete world snapshot should publish");

    var partialObserved = initialTarget with
    {
        Position = new Vector3Snapshot(4, 0, 0),
        DistanceToLocalPlayer = 4,
        CurrentHp = 0,
        MaxHp = 120,
        TargetServerObjectId = 8000,
        IsTargetingLocalPlayer = false,
        LootableRaw = 1,
        InteractionState = 37
    };
    var partial = new WorldObjectReadResult(
        WorldObjectReadCompleteness.Partial,
        new[]
        {
            new WorldObjectObservation(
                partialObserved,
                new WorldObjectFieldValidity(false, true, true, false, true, true))
        },
        CreateDmaWorldReadDiagnostics(startedAt.AddSeconds(5)),
        "injected partial read");
    var merged = api.StabilizeWorldObjectRead(context, partial, startedAt.AddSeconds(5));
    AssertFalse(!merged.Success, "partial world snapshot should merge into the stable snapshot");
    var mergedTarget = merged.Value!.Single(item => item.ServerObjectId == initialTarget.ServerObjectId);
    AssertEqual(2, merged.Value!.Count, "partial world snapshot should retain missing objects");
    AssertEqual(90u, mergedTarget.CurrentHp, "partial merge should hold failed hp");
    AssertEqual(120u, mergedTarget.MaxHp, "partial merge should publish valid max hp");

    var failedObservation = new WorldObjectObservation(
        partialObserved with { CurrentHp = 1, MaxHp = 1 },
        completeFields);
    var failed = new WorldObjectReadResult(
        WorldObjectReadCompleteness.Failed,
        new[] { failedObservation },
        CreateDmaWorldReadDiagnostics(startedAt.AddHours(1)),
        "transient dma failure");
    var held = api.StabilizeWorldObjectRead(context, failed, startedAt.AddHours(1));
    AssertFalse(!held.Success, "failed world read should return the stable snapshot even after the former ttl");
    var heldTarget = held.Value!.Single(item => item.ServerObjectId == initialTarget.ServerObjectId);
    AssertEqual(2, held.Value!.Count, "failed world read must not prune objects");
    AssertEqual(90u, heldTarget.CurrentHp, "failed world read must not update current hp");
    AssertEqual(120u, heldTarget.MaxHp, "failed world read should retain the published partial merge");

    var completeEmpty = new WorldObjectReadResult(
        WorldObjectReadCompleteness.Complete,
        Array.Empty<WorldObjectObservation>(),
        CreateDmaWorldReadDiagnostics(startedAt.AddHours(2)));
    var pruned = api.StabilizeWorldObjectRead(context, completeEmpty, startedAt.AddHours(2));
    AssertFalse(!pruned.Success || pruned.Value!.Count != 0, "complete empty world snapshot should prune prior objects");

    var sessionFailure = new WorldObjectReadResult(
        WorldObjectReadCompleteness.Failed,
        Array.Empty<WorldObjectObservation>(),
        CreateDmaWorldReadDiagnostics(startedAt.AddHours(3)),
        "Target process not found: Aion.bin");
    var invalidated = api.StabilizeWorldObjectRead(context, sessionFailure, startedAt.AddHours(3));
    var afterInvalidation = api.StabilizeWorldObjectRead(context, failed, startedAt.AddHours(4));
    AssertFalse(invalidated.Success, "process lifecycle failure should fail and invalidate the stable snapshot");
    AssertFalse(afterInvalidation.Success, "no snapshot should survive process lifecycle invalidation");
    return Task.CompletedTask;
}

static Task TestDmaInventorySnapshotMergesFieldsAndPrunesAsync()
{
    var api = new AionVmmGameApi(new AionVmmGameApiOptions(), NoOpRoadhogLogger.Instance);
    var context = CreateDmaSnapshotContext();
    var startedAt = new DateTimeOffset(2026, 8, 15, 3, 0, 0, TimeSpan.Zero);
    var first = new InventoryItemSnapshot(100, 1, "old-name", 7, 4, false, 24, 2, 90);
    var temporarilyMissing = new InventoryItemSnapshot(200, 2, "retained", 1, 5, false, 1, 4, 10);
    var completeFields = new InventoryItemFieldValidity(true, true, true, true, true, true, true, true);
    var initial = api.StabilizeInventoryRead(
        context,
        new InventoryReadResult(
            InventoryReadCompleteness.Complete,
            new[]
            {
                new InventoryItemObservation(first, completeFields),
                new InventoryItemObservation(temporarilyMissing, completeFields)
            },
            string.Empty),
        startedAt);
    AssertFalse(!initial.Success, "complete inventory snapshot should publish");

    var observedFirst = first with
    {
        TemplateId = 101,
        Name = "new-name",
        Count = 0,
        Slot = -1,
        QualityRank = 3
    };
    var added = new InventoryItemSnapshot(300, 3, "new-item", 2, 6, false, 24, 2, 20);
    var partial = api.StabilizeInventoryRead(
        context,
        new InventoryReadResult(
            InventoryReadCompleteness.Partial,
            new[]
            {
                new InventoryItemObservation(
                    observedFirst,
                    new InventoryItemFieldValidity(true, false, true, false, true, true, true, true)),
                new InventoryItemObservation(added, completeFields)
            },
            "inventory item tree cycle detected"),
        startedAt.AddMilliseconds(20));
    AssertFalse(!partial.Success, "partial inventory read should merge into the current snapshot");
    var mergedFirst = partial.Value!.Single(item => item.InstanceId == first.InstanceId);
    AssertEqual(3, partial.Value!.Count, "partial traversal must retain unobserved items");
    AssertEqual(101u, mergedFirst.TemplateId, "successful template id should update");
    AssertEqual("new-name", mergedFirst.Name, "successful item name should update");
    AssertEqual(7u, mergedFirst.Count, "failed count should retain last good value");
    AssertEqual(4, mergedFirst.Slot, "failed slot should retain last good value");

    var failed = api.StabilizeInventoryRead(
        context,
        new InventoryReadResult(
            InventoryReadCompleteness.Failed,
            Array.Empty<InventoryItemObservation>(),
            "transient inventory root read failure"),
        startedAt.AddSeconds(1));
    AssertFalse(!failed.Success || failed.Value!.Count != 3, "failed inventory read should hold the merged snapshot");

    var complete = api.StabilizeInventoryRead(
        context,
        new InventoryReadResult(
            InventoryReadCompleteness.Complete,
            new[]
            {
                new InventoryItemObservation(mergedFirst, completeFields),
                new InventoryItemObservation(added, completeFields)
            },
            string.Empty),
        startedAt.AddSeconds(2));
    AssertFalse(!complete.Success, "next complete inventory snapshot should publish");
    AssertFalse(
        complete.Value!.Any(item => item.InstanceId == temporarilyMissing.InstanceId),
        "only a complete traversal may prune an absent inventory item");
    return Task.CompletedTask;
}

