static Task TestDmaPetPartialMissingLinkedActorRetainsIdentityAsync()
{
    const uint petServerObjectId = 2000;
    var previous = CreateLocalPetRoster(
        isSummoned: true,
        currentHp: 80,
        maxHp: 100,
        petServerObjectId: petServerObjectId);
