sealed class InMemoryBagCleanupNameListStore : IBagCleanupNameListStore
{
    private BagCleanupNameListsDocument _document;
    private BagCleanupNameListsDocument? _pendingDocument;
    private TaskCompletionSource<OperationResult>? _pendingSave;

    public InMemoryBagCleanupNameListStore(BagCleanupNameListsDocument? document = null)
    {
        _document = document?.Clone() ?? new BagCleanupNameListsDocument();
    }

    public string FilePath => "memory://bag-cleanup-name-lists.json";

    public int SaveCount { get; private set; }

    public bool FailSaves { get; set; }

    public bool BlockSaves { get; set; }

    public BagCleanupNameListsDocument Document => _document.Clone();

    public Task<OperationResult<BagCleanupNameListsLoadResult>> LoadAsync(
        CancellationToken cancellationToken = default)
    {
        return Task.FromResult(OperationResult<BagCleanupNameListsLoadResult>.Ok(
            new BagCleanupNameListsLoadResult(_document, BagCleanupNameListsSource.Json)));
    }

    public Task<OperationResult> SaveAsync(
        BagCleanupNameListsDocument document,
        CancellationToken cancellationToken = default)
    {
        SaveCount++;
        if (FailSaves)
        {
            return Task.FromResult(OperationResult.Fail("simulated name-list save failure"));
        }

        if (BlockSaves)
        {
            _pendingDocument = document.Clone();
            _pendingSave = new TaskCompletionSource<OperationResult>();
            return _pendingSave.Task;
        }

        _document = document.Clone();
        return Task.FromResult(OperationResult.Ok());
    }

    public void CompletePendingSave()
    {
        if (_pendingSave is null || _pendingDocument is null)
        {
            throw new InvalidOperationException("A blocked name-list save should be pending.");
        }

        _document = _pendingDocument!.Clone();
        BlockSaves = false;
        var pendingSave = _pendingSave!;
        _pendingDocument = null;
        _pendingSave = null;
        pendingSave.SetResult(OperationResult.Ok());
    }
}

sealed class InMemoryHardwareDeviceResolver : IHardwareDeviceResolver
{
    private readonly IReadOnlyList<HardwareDeviceFeature> _devices;

    public InMemoryHardwareDeviceResolver(params HardwareDeviceFeature[] devices)
    {
        _devices = devices;
    }

    public IReadOnlyList<HardwareDeviceFeature> ListDevices()
    {
        return _devices;
    }

    public OperationResult<HardwareBinding> BindByKey(string accountName, string hardwareKey)
    {
        var device = _devices.FirstOrDefault(item =>
            string.Equals(item.BindingKey.Trim(), hardwareKey.Trim(), StringComparison.OrdinalIgnoreCase) ||
            item.AliasKeys.Any(alias => string.Equals(alias.Trim(), hardwareKey.Trim(), StringComparison.OrdinalIgnoreCase)));
        return device is null
            ? OperationResult<HardwareBinding>.Fail("Hardware device not found: " + hardwareKey)
            : OperationResult<HardwareBinding>.Ok(CreateBinding(accountName, device));
    }

    public OperationResult<HardwareBinding> TryAutoBind(string accountName)
    {
        return _devices.Count == 0
            ? OperationResult<HardwareBinding>.Fail("Hardware device not found.")
            : OperationResult<HardwareBinding>.Ok(CreateBinding(accountName, _devices[0]));
    }

    private static HardwareBinding CreateBinding(string accountName, HardwareDeviceFeature device)
    {
        return new HardwareBinding(
            accountName,
            device.BindingKey,
            device.BindingKind,
            device.BindingConfidence,
            device.DeviceInstanceId,
            device.ParentInstanceId,
            device.ContainerId,
            device.HardwareId,
            device.LocationKey,
            device.DisplayName,
            device.Manufacturer,
            device.VmmDeviceName,
            device.AliasKeys,
            DateTimeOffset.Now);
    }
}

